// Üretilen dosya: tool/ozgun/uret.py. Fizik ve Astronomi · Sığaçlar (kondansatörler), alternatif akım devreleri, rezonans, transformatörler ve elektrik enerjisi iletimi (orta).
const ozPhysics17Orta = <(String, String, List<String>, String)>[
  ('Boşlukta paralel levhalı bir sığacın levhaları tamamen yalıtkan bir maddeyle doldurulduğunda dielektrik içindeki moleküllerin kutuplanması levhalar arasındaki elektrik alanı nasıl etkiler (yük sabitken)?', 'Kutuplanma yükleri zıt yönlü iç alan oluşturarak net elektrik alanı azaltır', ['Kutuplanma yükleri aynı yönlü alan oluşturarak net elektrik alanı artırır', 'Yalıtkan içindeki net elektrik alan sıfırlanarak tamamen yok olur', 'Moleküller hareket edemediği için net elektrik alan şiddeti hiç değişmez'], 'Dielektrik kutuplandığında levha yüklerine zıt işaretli yüzey yükleri indüklenir; bu da içerideki net elektrik alanı zayıflatır.'),
  ('Bir sığacın sığası C, yükü Q ve enerjisi E\'dir. Sığacın sığası sabit kalmak koşuluyla üzerindeki yük 3 katına çıkarılırsa depolanan enerji nasıl değişir?', '9 katına çıkar', ['3 katına çıkar', '6 katına çıkar', '√3 katına çıkar'], 'E = Q²/(2C) bağıntısına göre C sabitken enerji yükün karesiyle doğru orantılıdır; yük 3 katına çıkınca enerji 9 katına çıkar.'),
  ('Kenar uzunluğu a olan kare biçimli paralel levhalardan oluşan bir sığacın levha kenar uzunlukları 2a yapılıp levhalar arası uzaklık yarıya indirilirse sığası kaç katına çıkar?', '8 katına', ['4 katına', '2 katına', '16 katına'], 'Kare levhanın alanı A = a² iken kenar 2a olunca yeni alan 4A olur. Uzaklık d/2 yapılınca C\' = ε·(4A)/(d/2) = 8C olur.'),
  ('Dairesel levhalara sahip bir düzlem sığacın levha yarıçapı r, levhalar arası uzaklığı d\'dir. Levha yarıçapı 3r ve uzaklık 3d yapılırsa yeni sığa başlangıçtakinin kaç katı olur?', '3 katı', ['1 katı', '9 katı', '1/3 katı'], 'Daire alanı πr² olduğundan yarıçap 3r yapıldığında alan 9 katına çıkar. Uzaklık 3 katına çıktığından C\' = (9/3)C = 3C olur.'),
  ('Yüzey alanı 0,2 m² ve levhalar arası uzaklığı 1,77 mm olan hava ortamındaki düzlem sığacın sığası kaç nF\'dır? (ε₀ = 8,85×10⁻¹² F/m)', '1 nF', ['10 nF', '0,1 nF', '100 nF'], 'C = ε₀·A/d = (8,85×10⁻¹² × 0,2) / (1,77×10⁻³) = 1,77×10⁻¹² / 1,77×10⁻³ = 10⁻⁹ F = 1 nF bulunur.'),
  ('Hava ortamında sığası 15 pF olan paralel levhalı sığacın levhaları arası bağıl dielektrik katsayısı κ = 4 olan mika ile tamamen doldurulursa yeni sığası kaç pF olur?', '60 pF', ['3,75 pF', '19 pF', '240 pF'], 'Dielektrik tamamen doldurulduğunda C\' = κ·C₀ bağıntısından C\' = 4 × 15 pF = 60 pF elde edilir.'),
  ('Sığası 8 µF olan bir sığaçta depolanan enerjinin 0,16 J olması için sığaçta biriken yük miktarı kaç mC olmalıdır?', '1,6 mC', ['3,2 mC', '0,8 mC', '6,4 mC'], 'E = Q²/(2C) => 0,16 = Q² / (2 × 8×10⁻⁶) => Q² = 2,56×10⁻⁶ => Q = 1,6×10⁻³ C = 1,6 mC bulunur.'),
  ('Bir sığaç sabit bir üretece bağlandığında 24 µC yük ve 72 µJ enerji depolamaktadır. Bu sığacın sığası kaç µF\'dır?', '4 µF', ['2 µF', '6 µF', '8 µF'], 'Önce E = (1/2)·Q·V => 72 = 0,5 × 24 × V => V = 6 V bulunur. Ardından C = Q/V = 24 µC / 6 V = 4 µF hesaplanır.'),
  ('Paralel levhaları arasındaki uzaklık 4 mm olan bir sığacın arasına dielektrik dayanımı 15×10⁶ V/m olan yalıtkan konulmuştur. Sığacın delinmemesi için uygulanabilecek maksimum gerilim kaç kV\'dur?', '60 kV', ['3,75 kV', '30 kV', '120 kV'], 'V_max = E_max · d bağıntısından V_max = (15×10⁶ V/m) × (4×10⁻³ m) = 60×10³ V = 60 kV bulunur.'),
  ('Üretece bağlı paralel levhalı bir sığacın sığası 10 µF, gerilimi 30 V\'tur. Üretecin gerilimi 50 V\'a çıkarılırsa sığaçta depolanan enerji kaç mJ artar?', '8 mJ', ['4,5 mJ', '12,5 mJ', '2 mJ'], 'ΔE = (1/2)·C·(V₂² - V₁²) = 0,5 × 10×10⁻⁶ × (2500 - 900) = 5×10⁻⁶ × 1600 = 8×10⁻³ J = 8 mJ artar.'),
  ('Sabit V gerilimli bir üretece bağlı paralel levhalı sığacın levhaları arasındaki uzaklık artırılırken sığacın yükü (Q) ve levhalar arası elektrik alan şiddeti (E) nasıl değişir?', 'Yük azalır, elektrik alan şiddeti azalır', ['Yük değişmez, elektrik alan şiddeti azalır', 'Yük azalır, elektrik alan şiddeti değişmez', 'Yük artar, elektrik alan şiddeti azalır'], 'Üretece bağlıyken V sabittir. d artınca C = εA/d azalır, Q = CV azalır ve E = V/d azalır.'),
  ('Bir üreteçle yüklendikten sonra üreteçten ayrılan yalıtılmış bir sığacın levhaları arasındaki uzaklık artırılırsa potansiyel farkı (V) ve elektrik alan şiddeti (E) nasıl değişir (kenar etkileri ihmal)?', 'Potansiyel farkı artar, elektrik alan şiddeti değişmez', ['Potansiyel farkı değişmez, elektrik alan şiddeti azalır', 'Potansiyel farkı artar, elektrik alan şiddeti artar', 'Potansiyel farkı azalır, elektrik alan şiddeti değişmez'], 'Üreteçten ayrıldığında Q sabittir. d artınca C azalır, V = Q/C artar; E = Q/(εA) olduğundan d\'den bağımsızdır ve değişmez.'),
  ('Sabit gerilimli üretece bağlı bir hava sığacının levhaları arasına yalıtkan bir levha tamamen sokulursa sığaçta depolanan enerji (U) ve levhalar arası elektrik alan (E) nasıl değişir?', 'Enerji artar, elektrik alan değişmez', ['Enerji azalır, elektrik alan azalır', 'Enerji artar, elektrik alan azalır', 'Enerji değişmez, elektrik alan değişmez'], 'Üretece bağlı olduğundan V ve d sabittir; E = V/d değişmez. Yalıtkan C\'yi artırır, U = (1/2)CV² olduğundan enerji artar.'),
  ('Üreteçle yüklenip devreden çıkarılan bir hava sığacının levhaları arasına bağıl dielektrik katsayısı κ > 1 olan yalıtkan yerleştirilirse sığacın enerjisi (U) ve potansiyel farkı (V) nasıl değişir?', 'Enerji azalır, potansiyel farkı azalır', ['Enerji artar, potansiyel farkı değişmez', 'Enerji azalır, potansiyel farkı artar', 'Enerji değişmez, potansiyel farkı azalır'], 'Üreteçten ayrıldığı için Q sabittir. C, κ katına çıkınca V = Q/C azalır ve U = Q²/(2C) azalır.'),
  ('Yüklü ve üreteçten ayrılmış paralel levhalı bir sığacın levhalarını birbirinden uzaklaştırmak için dış kuvvetin pozitif iş yapması gerekir. Bu iş sığaçta hangi değişime dönüşür?', 'Sığaçta depolanan elektriksel potansiyel enerjinin artışına', ['Levhalarda biriken toplam elektrik yükü miktarının artışına', 'Ortamın dielektrik geçirgenlik katsayısının büyümesine', 'Levhalar arasındaki düzgün elektrik alan şiddetinin artışına'], 'Zıt yüklü levhalar birbirini çeker; onları ayırmak için yapılan mekanik iş, Q sabitken azalan C nedeniyle artan U = Q²/(2C) enerjisine dönüşür.'),
  ('Sabit gerilimli üretece bağlı bir sığacın levhaları birbirine yaklaştırıldığında hem üreteç iş yapar hem de sığacın enerjisi artar. Bu süreçte üretecin üzerinden geçen yük hareketi nasıldır?', 'Üreteçten sığaca ek yük geçişi olur', ['Sığaçtan üretece doğru yük geri boşalır', 'Devrede hiçbir yük hareketi gerçekleşmez', 'Yalnızca pozitif levhadan negatif levhaya hava üzerinden yük atlar'], 'Levhalar yaklaşınca C artar; V sabit olduğundan Q = CV gereği sığacın yükü artmalı, yani üreteç sığaca ek yük pompalamalıdır.'),
  ('Üretece bağlı yüklü bir sığacın levhaları birbirinden uzaklaştırılırsa sığaç ile üreteç arasındaki yük alışverişi için ne söylenebilir?', 'Sığacın sığası azaldığı için fazla yük sığaçtan üretece geri döner', ['Sığacın gerilimi düştüğü için üreteçten sığaca yük akışı olur', 'Yalıtkan ortam hava olduğu için yük miktarı sabit kalır', 'Sığaç üzerindeki tüm yük sıfırlanana kadar üretece boşalır'], 'd artınca C azalır; V üreteç tarafından sabit tutulduğundan Q = CV azalır ve sığaçtaki yükün bir kısmı üretece geri akar.'),
  ('Farklı iki sığaç olan X ve Y\'ye ait yük-gerilim (Q-V) doğrularından X doğrusunun gerilim ekseniyle yaptığı dar açı 60°, Y doğrusunun ise 30°\'dir. Buna göre sığaların oranı Cx/Cy kaçtır?', '3', ['√3', '1/3', '2'], 'Q-V grafiğinde eğim tanα = Q/V = C\'dir. Cx/Cy = tan60° / tan30° = √3 / (1/√3) = 3 bulunur.'),
  ('Özdeş iki paralel levhalı sığaçtan K üretece bağlı bırakılırken, L aynı üreteçle yüklenip üreteçten ayrılıyor. Her ikisinin de levhaları arası uzaklık yarıya indirilirse son enerjilerinin oranı Ek/El kaç olur?', '4', ['2', '1', '1/2'], 'Başlangıçta ikisinin de enerjisi E₀ olsun. d yarıya inince C iki katına (2C) çıkar. K\'de V sabit: Ek = (1/2)(2C)V² = 2E₀. L\'de Q sabit: El = Q²/(2·2C) = E₀/2. Oran Ek/El = 2E₀ / (E₀/2) = 4 olur.'),
  ('Özdeş M ve N hava sığaçları aynı V gerilimiyle yüklendikten sonra M üretece bağlı kalıyor, N üreteçten ayrılıyor. Her ikisinin de levhaları arasına κ = 3 olan yalıtkan tamamen doldurulursa son gerilimlerinin oranı Vm/Vn kaç olur?', '3', ['1/3', '9', '1'], 'M üretece bağlı olduğundan Vm = V kalır. N üreteçten ayrı olduğundan Q sabit, sığası 3C olunca Vn = Q/(3C) = V/3 olur. Oran Vm/Vn = V / (V/3) = 3 bulunur.'),
  ('Yüklü ve yalıtılmış paralel levhalı bir sığacın levhalarından biri sabit tutulurken diğeri serbest bırakılırsa levhalar birbirine doğru hızlanır. Çarpışmadan hemen önceki süreçte hangi nicelik sabit kalır?', 'Levhalar arasındaki elektrik alanın büyüklüğü', ['Levhalar arasındaki potansiyel farkı', 'Sığacın sığası', 'Sığaçta depolanan elektriksel potansiyel enerji'], 'Yalıtılmış sığaçta Q sabittir; kenar etkileri ihmal edildiğinde E = Q/(εA) uzaklığa bağlı olmadığından elektrik alan büyüklüğü sabit kalır.'),
  ('Levhaları yatay konumda olan ve sabit V gerilimli üretece bağlı paralel levhalı bir sığacın içinde yüklü bir yağ damlası havada dengede durmaktadır. Levhalar arası uzaklık artırılırsa damlanın hareketi ne olur?', 'Aşağı doğru (yerçekimi yönünde) ivmelenir', ['Yukarı doğru ivmelenir', 'Hareketsiz dengede kalmaya devam eder', 'Sabit hızla yukarı doğru yükselir'], 'Başlangıçta qE = mg ile dengededir. Üretece bağlıyken d artırılırsa E = V/d azalır; elektriksel kuvvet qE < mg olacağından damla aşağı ivmelenir.'),
  ('Levhaları yatay olan paralel levhalı bir sığaç üreteçle yüklendikten sonra üreteçten ayrılıyor. İçinde asılı dengede duran yüklü bir tanecik varken levhalar arası uzaklık biraz artırılırsa tanecik nasıl hareket eder (kenar etkileri önemsiz)?', 'Dengesi bozulmaz, olduğu yerde hareketsiz kalır', ['Yerçekimi yönünde ivmelenerek alt levhaya çarpar', 'Elektriksel kuvvet yönünde ivmelenerek üst levhaya çarpar', 'İki levha arasında basit harmonik hareket yapar'], 'Üreteçten ayrılmış sığaçta Q sabittir ve E = Q/(εA) levhalar arası uzaklıktan bağımsızdır. Elektrik alan değişmediği için qE = mg dengesi korunur.'),
  ('Yalıtılmış bir düzlem sığaç 120 V gerilime kadar yüklenip üreteçten ayrılıyor. Ardından levhaları arası κ = 2,5 olan bir dielektrikle tamamen doldurulursa levhalar arası yeni gerilim kaç V olur?', '48 V', ['300 V', '60 V', '24 V'], 'Yük sabitken C\' = κ·C olduğundan V\' = V / κ = 120 V / 2,5 = 48 V elde edilir.'),
  ('Sabit 20 V gerilimli üretece bağlı 6 µF sığalı hava sığacının levhaları arası κ = 4 olan yalıtkanla tamamen dolduruluyor. Bu işlem sırasında üreteçten sığaca geçen ek yük miktarı kaç µC\'dur?', '360 µC', ['480 µC', '120 µC', '240 µC'], 'İlk yük Q₁ = C·V = 6 × 20 = 120 µC. Son sığa C₂ = 4 × 6 = 24 µF ve son yük Q₂ = 24 × 20 = 480 µC. Ek yük ΔQ = 480 - 120 = 360 µC olur.'),
  ('Yüzey alanı A, levhalar arası uzaklığı d olan hava sığacı Q yüküyle yüklenip üreteçten ayrılmıştır. Başlangıç enerjisi 40 mJ olan sığacın levhaları arası uzaklık 2,5d yapılırsa dış kuvvetlerin yaptığı en az iş kaç mJ olur?', '60 mJ', ['100 mJ', '24 mJ', '80 mJ'], 'Q sabitken U = Q²/(2C) ve C ∝ 1/d olduğundan enerji d ile doğru orantılıdır. Uzaklık 2,5 katına çıkınca U₂ = 2,5 × 40 = 100 mJ olur. Yapılan iş W = U₂ - U₁ = 100 - 40 = 60 mJ\'dür.'),
  ('Paralel levhalı bir sığacın alanı A, levhalar arası uzaklığı d ve boşluktaki sığası 12 pF\'dır. Levhalar arasına yüzey alanı A, kalınlığı d/2 ve bağıl geçirgenliği κ = 3 olan bir cam levha levhalara paralel yerleştirilirse yeni sığa kaç pF olur?', '18 pF', ['24 pF', '36 pF', '16 pF'], 'Sistem kalınlığı d/2 olan hava (C₁ = ε₀A/(d/2) = 2C₀ = 24 pF) ve kalınlığı d/2 olan cam (C₂ = 3ε₀A/(d/2) = 6C₀ = 72 pF) sığaçların seri bağlanması gibidir: C_eş = (24×72)/(24+72) = 1728/96 = 18 pF.'),
  ('Boşluktaki sığası 10 µF olan paralel levhalı bir sığacın levha alanının yarısını (A/2) tam d kalınlığında κ = 5 olan yalıtkan dolduracak, diğer yarısı hava kalacak biçimde yerleştirilirse toplam sığa kaç µF olur?', '30 µF', ['25 µF', '50 µF', '15 µF'], 'Yan yana (alan bölünmesi) yerleştirilen dielektrikler paralel bağlı iki sığaç oluşturur. Hava kısmı C₁ = ε₀(A/2)/d = C₀/2 = 5 µF, yalıtkan kısmı C₂ = 5·C₀/2 = 25 µF olur. Paralel toplam C_eş = 5 + 25 = 30 µF bulunur.'),
  ('Bir mühendis yüksek enerji yoğunluklu küçük boyutlu bir sığaç tasarlamak istiyor. Hem sığayı büyütmek hem de yüksek gerilime dayanmasını sağlamak için levhalar arası uzaklık d ve yalıtkan seçimi nasıl değerlendirilmelidir?', 'Hem bağıl dielektrik katsayısı hem de dielektrik dayanımı yüksek bir yalıtkan seçilerek d olabildiğince küçük tutulmalıdır', ['Sığayı artırmak için d çok büyük seçilmeli ve yalıtkan olarak yalnızca kuru hava kullanılmalıdır', 'Dielektrik dayanımı düşük fakat iletkenliği yüksek bir yarı iletken malzeme kullanılarak d sıfıra yaklaştırılmalıdır', 'Maksimum enerji depolamak için yalıtkan tamamen çıkarılıp levhalar birbirine temas ettirilmelidir'], 'U_max = (1/2)(κε₀A/d)(E_max·d)² = (1/2)κε₀(A·d)E_max² ve küçük hacim (küçük A·d) içinde yüksek C ve yüksek gerilim için yüksek κ ve yüksek E_max gerekir; d ise delinmeyecek kadar ince tutulur.'),
  ('Laboratuvarda yüklü bir sığacın uçlarına iç direnci sonsuz kabul edilen ideal bir elektrostatik voltmetre bağlıyken levhalar arasına plastik bir cetvel sokulduğunda voltmetrenin gösterdiği değerin düştüğü gözleniyor. Bu deneyden hangi sonuç çıkarılabilir?', 'Sığaç üretece bağlı değildir; plastik cetvel sığayı artırdığı için sabit yük altında gerilim azalmıştır', ['Plastik cetvel iletken olduğu için levhalardaki yüklerin yarısını toprağa akıtmıştır', 'Sığaç sabit bir üretece bağlıdır ve cetvel üretecin elektromotor kuvvetini düşürmüştür', 'Plastik cetvelin bağıl dielektrik katsayısı boşluğunkinden (1\'den) daha küçüktür'], 'İdeal voltmetre yük çekmez (Q sabit). Plastik yalıtkandır (κ > 1), araya girince C artar ve V = Q/C azalır; eğer üretece bağlı olsaydı V değişmezdi.'),
  ('Aralarında d uzaklığı bulunan paralel levhalı bir hava sığacı üreteçten ayrılmış ve Q yüküne sahiptir. Levhalar arasına levhalara değmeyecek şekilde d/3 kalınlığında yüksüz iletken bir metal plaka paralel olarak sokulursa sığacın sığası nasıl değişir?', 'Etkili hava aralığı 2d/3\'e düştüğü için sığa 1,5 katına çıkar', ['Metal plaka kısa devre yaratacağı için sığa sıfıra düşer', 'Metal plakanın dielektrik katsayısı sıfır olduğundan sığa üçte birine iner', 'Plaka yüksüz olduğu için elektrik alanı etkilemez ve sığa değişmez'], 'İletken plaka içinde elektrik alan sıfırdır; elektrik alan yalnızca kalan d - d/3 = 2d/3\'lük hava boşluğunda var olur. Dolayısıyla yeni sığa C\' = ε₀A/(2d/3) = 1,5 C₀ olur.'),
  ('Hava ortamında sığası 12 µF olan paralel levhalı bir sığaç 15 V\'luk üreteçle yüklenip üreteçten ayrılıyor. Daha sonra levhalar arası uzaklık başlangıçtakinin 3/2 katına çıkarılırsa son potansiyel farkı kaç V olur?', '22,5 V', ['10 V', '30 V', '18 V'], 'Üreteçten ayrıldığı için Q sabittir. Uzaklık 3/2 katına çıkınca C\' = (2/3)C olur; V\' = Q/C\' = (3/2)V = 1,5 × 15 V = 22,5 V bulunur.'),
  ('Bir sığacın üzerindeki yük 40 µC artırıldığında uçları arasındaki gerilim 8 V artmaktadır. Bu sığacın başlangıçta yüksüz olduğu bilindiğine göre gerilimi 16 V yapıldığında depoladığı enerji kaç µJ olur?', '640 µJ', ['320 µJ', '1280 µJ', '160 µJ'], 'Sığa C = ΔQ / ΔV = 40 µC / 8 V = 5 µF\'dır. 16 V gerilimde enerji E = (1/2)·5 µF·16² = 2,5 × 256 = 640 µJ olur.'),
  ('Sabit V gerilimli üretece bağlı paralel levhalı bir sığacın levhalarının birbirine bakan ortak yüzey alanı levhalar kaydırılarak yarıya indirilirse (d sabit), levhalar arası elektrik alan (E) ve sığacın yükü (Q) nasıl değişir?', 'Elektrik alan değişmez, sığacın yükü yarıya iner', ['Elektrik alan yarıya iner, sığacın yükü değişmez', 'Elektrik alan iki katına çıkar, sığacın yükü yarıya iner', 'Elektrik alan da sığacın yükü de yarıya iner'], 'V ve d sabit olduğundan E = V/d değişmez. Ortak alan A/2 olunca C yarıya iner; Q = CV gereği sığacın yükü de yarıya iner.'),
  ('Seri bağlı C₁ = C ve C₂ = 3C sığaçları bir doğru akım üretecine bağlandığında C₁ sığacında depolanan enerjinin C₂ sığacında depolanan enerjiye oranı (E₁/E₂) kaçtır?', '3', ['1/3', '9', '1/9'], 'Seri bağlı sığaçlarda yük Q eşittir. Enerji E = Q²/(2C) ile sığayla ters orantılı olduğundan E₁/E₂ = C₂/C₁ = 3C / C = 3 olur.'),
  ('Paralel bağlı C₁ = 2C ve C₂ = 5C sığaçları aynı üretece bağlandığında depoladıkları enerjilerin oranı (E₁/E₂) kaç olur?', '2/5', ['5/2', '4/25', '1'], 'Paralel bağlı sığaçlarda V eşittir. Enerji E = (1/2)CV² bağıntısına göre sığayla doğru orantılıdır: E₁/E₂ = 2C / 5C = 2/5 bulunur.'),
  ('Sığaları C₁ = 4 µF ve C₂ = 12 µF olan iki sığaç birbirine paralel bağlandıktan sonra bu gruba C₃ = 16 µF\'lık üçüncü bir sığaç seri bağlanıyor. Tüm sistemin eşdeğer sığası kaç µF\'dır?', '8 µF', ['32 µF', '6 µF', '12 µF'], 'Paralel grubun eşdeğeri C₁₂ = 4 + 12 = 16 µF olur. Buna 16 µF seri bağlandığında C_eş = (16 × 16) / (16 + 16) = 8 µF bulunur.'),
  ('Sığaları 6 µF ve 3 µF olan iki sığaç seri bağlanıp bu kola 5 µF\'lık bir sığaç paralel bağlanıyor. Uçlar arasına 10 V gerilim uygulandığında 6 µF\'lık sığacın uçları arasındaki gerilim kaç V olur?', '10/3 V', ['20/3 V', '5 V', '10 V'], 'Üst seri kula da 10 V düşer. Seri koldaki eşdeğer sığa (6×3)/(6+3) = 2 µF ve kolun yükü Q = 2 × 10 = 20 µC\'dur. 6 µF\'lık sığacın gerilimi V₆ = Q / C₆ = 20 / 6 = 10/3 V olur.'),
  ('Seri bağlı C₁ = 2 µF, C₂ = 3 µF ve C₃ = 6 µF sığaçlarından oluşan bir devreye 36 V gerilim uygulanıyor. Buna göre C₂ = 3 µF\'lık sığaçta depolanan enerji kaç µJ\'dür?', '216 µJ', ['648 µJ', '108 µJ', '432 µJ'], '1/C_eş = 1/2 + 1/3 + 1/6 = 1 => C_eş = 1 µF. Toplam yük Q = 1 µF × 36 V = 36 µC (hepsinde eşit). E₂ = Q²/(2C₂) = 36² / (2 × 3) = 1296 / 6 = 216 µJ bulunur.'),
  ('Sığası 4 µF olan K sığacı 30 V ile, sığası 6 µF olan L sığacı 10 V ile yüklendikten sonra üreteçlerden ayrılıyor. Aynı işaretli levhaları birleştirilecek biçimde birbirine paralel bağlanırlarsa ortak potansiyel kaç V olur?', '18 V', ['20 V', '6 V', '15 V'], 'İlk yükler Qk = 4 × 30 = 120 µC ve Ql = 6 × 10 = 60 µC. Aynı işaretli bağlandıklarında Q_top = 120 + 60 = 180 µC. V_ort = 180 / (4 + 6) = 18 V olur.'),
  ('Sığası 5 µF olan X sığacı 40 V gerilimle, sığası 3 µF olan Y sığacı ise 20 V gerilimle yüklenip üreteçlerden çıkarılıyor. Zıt işaretli levhaları birbirine bağlanacak şekilde paralel birleştirilirlerse Y sığacının son yükünün büyüklüğü kaç µC olur?', '52,5 µC', ['97,5 µC', '82,5 µC', '17,5 µC'], 'Qx = 5 × 40 = 200 µC, Qy = 3 × 20 = 60 µC. Zıt bağlanınca Q_net = 200 - 60 = 140 µC. Ortak gerilim V_ort = 140 / (5 + 3) = 17,5 V. Y\'nin son yükü Qy\' = Cy · V_ort = 3 × 17,5 = 52,5 µC olur.'),
  ('Sığası 2 µF olan sığaç 50 V gerilimle yüklendikten sonra üreteçten ayrılıp yüksüz 8 µF\'lık bir sığaca paralel bağlanıyor. Yük paylaşımı tamamlandığında sistemde ısı/ışınım olarak kaybolan toplam enerji kaç mJ\'dür?', '2 mJ', ['2,5 mJ', '0,5 mJ', '1,5 mJ'], 'İlk enerji E_ilk = (1/2)·2×10⁻⁶·50² = 2,5 mJ ve Q = 100 µC. Son durumda C_top = 10 µF, E_son = Q²/(2C_top) = (10⁻⁴)² / (2×10⁻⁵) = 0,5 mJ. Kayıp enerji ΔE = 2,5 - 0,5 = 2 mJ olur.'),
  ('Her birinin sığası 6 µF ve dayanabileceği maksimum gerilim 20 V olan iki özdeş sığactan birincisinin önüne sığası 3 µF ve dayanma gerilimi 50 V olan bir sığaç seri bağlanıyor. Bu iki seri sığaçtan (6 µF ve 3 µF) oluşan kola uygulanabilecek maksimum toplam gerilim kaç V\'tur?', '60 V', ['70 V', '75 V', '45 V'], 'Seri kolda maksimum yük her sığacın Q_max = C·V_max değerlerinin en küçüğü ile sınırlıdır. Q₁_max = 6 × 20 = 120 µC; Q₂_max = 3 × 50 = 150 µC. Güvenli sınır Q = 120 µC\'dur. C_eş = (6×3)/(6+3) = 2 µF olduğundan V_top_max = Q / C_eş = 120 / 2 = 60 V olur.'),
  ('Birbirine seri bağlı 4 µF ve 12 µF sığaçlarına uygulanabilecek maksimum gerilimler sırasıyla 30 V ve 15 V\'tur. Hiçbir sığacın zarar görmemesi için bu seri devreye en fazla kaç V gerilim uygulanabilir?', '40 V', ['45 V', '60 V', '20 V'], 'İzin verilen maksimum yükler: Q₁_max = 4 × 30 = 120 µC ve Q₂_max = 12 × 15 = 180 µC. Küçük olan Q = 120 µC seçilir. C_eş = (4×12)/(4+12) = 3 µF olduğundan V_max = 120 µC / 3 µF = 40 V bulunur.'),
  ('Üç özdeş sığaç kullanılarak oluşturulabilecek farklı bağlantı kombinasyonlarında en büyük eşdeğer sığa 18 µF ise aynı üç sığaçla elde edilebilecek en küçük eşdeğer sığa kaç µF\'dır?', '2 µF', ['6 µF', '3 µF', '9 µF'], 'En büyük eşdeğer sığa üçü paralelken oluşur: 3C = 18 µF => C = 6 µF. En küçük eşdeğer sığa üçü seriyken oluşur: C/3 = 6 / 3 = 2 µF bulunur.'),
  ('Özdeş üç sığacın ikisi birbirine paralel, üçüncüsü ise onlara seri bağlandığında eşdeğer sığa 8 µF oluyor. Buna göre tek bir sığacın sığası kaç µF\'dır?', '12 µF', ['16 µF', '6 µF', '24 µF'], 'Paralel ikili 2C, buna seri bağlanan C ile eşdeğer sığa (2C · C) / (2C + C) = (2/3)C olur. (2/3)C = 8 µF => C = 12 µF bulunur.'),
  ('Yarıçapları r ve 3r olan iki iletken küreden birincisinin yükü +10q, ikincisinin yükü -2q\'dur. Küreler birbirine yeterince uzaktayken ince bir iletken telle birleştirilirse büyük kürenin son yükü ne olur?', '+6q', ['+2q', '+4q', '+9q'], 'Kürelerin sığaları yarıçaplarıyla doğru orantılıdır: C₁ = C, C₂ = 3C. Toplam yük Q_net = +10q - 2q = +8q. Büyük kürenin payı Q₂\' = Q_net · [C₂ / (C₁ + C₂)] = +8q × (3/4) = +6q olur.'),
  ('Özdeş X ve Y hava sığaçları seri bağlanarak sabit V gerilimli bir üretece takılmıştır. Üreteç bağlantısı kesilmeden yalnız X sığacının levhaları arasına κ = 3 olan yalıtkan tamamen yerleştirilirse X ve Y\'nin uçları arasındaki potansiyel farkları (Vx, Vy) nasıl değişir?', 'Vx azalır, Vy artar', ['Vx artar, Vy azalır', 'Her ikisi de değişmez', 'Her ikisi de azalır'], 'Başlangıçta Cx = Cy = C olduğundan Vx = Vy = V/2\'dir. Yalıtkan konulunca Cx = 3C olur, Cy = C kalır. Seri kolda gerilim sığayla ters orantılı paylaşıldığından Vx\' = V/4 (azalır) ve Vy\' = 3V/4 (artar) olur.'),
  ('Özdeş K ve L hava sığaçları seri bağlanıp V gerilimli üreteçle yüklendikten sonra üreteç devreden çıkarılıyor. Uçları açık kalan seri devrede yalnız K sığacının levhaları arasına κ = 2 olan yalıtkan doldurulursa K ve L\'nin gerilimleri (Vk, Vl) nasıl değişir?', 'Vk yarıya iner, Vl değişmez', ['Vk yarıya iner, Vl iki katına çıkar', 'Her ikisi de yarıya iner', 'Ne Vk ne de Vl değişir'], 'Üreteç çıkarılıp uçlar açık bırakıldığında seri koldaki yük Q değişemez! L\'nin yükü ve sığası değişmediğinden Vl = Q/C sabit kalır. K\'nin sığası 2C\'ye çıktığından Vk\' = Q/(2C) = Vk/2 olur.'),
  ('Farklı potansiyellere sahip iki sığaç üreteçten bağımsız olarak paralel bağlandığında toplam yük korunduğu halde toplam elektriksel potansiyel enerjinin her zaman azaldığı görülür. Bu enerji farkına ne olur?', 'Bağlantı tellerinin direncinde ısı enerjisine ve kısmen elektromanyetik ışıma enerjisine dönüşür', ['Sığaçların dielektrik maddelerinin kütlesinde artışa dönüşür', 'Tamamı sığaç levhalarının kinetik enerjisi olarak sonsuza dek saklanır', 'Hiçbir yere dönüşmez; enerjinin korunumu yasası sığaç devrelerinde geçerli değildir'], 'Süperiletken olsalar bile ivmeli yüklerden elektromanyetik ışıma yayılır, gerçek devrelerde ise akım geçerken bağlantı tellerinde Joule ısısı olarak harcanır.'),
  ('İki farklı yüklü sığaç zıt kutupları birbirine bağlanacak şekilde paralel birleştirildiğinde son durumda her iki sığacın da geriliminin ve enerjisinin tamamen sıfır olması için başlangıçta hangi koşul sağlanmalıdır?', 'İki sığacın başlangıçtaki yük büyüklüklerinin birbirine eşit olması (Q₁ = Q₂)', ['İki sığacın başlangıçtaki gerilimlerinin birbirine eşit olması (V₁ = V₂)', 'İki sığacın sığalarının birbirine eşit olması (C₁ = C₂)', 'İki sığacın başlangıçtaki enerjilerinin birbirine eşit olması (E₁ = E₂)'], 'Zıt bağlamada V_ort = |Q₁ - Q₂| / (C₁ + C₂) olduğundan ortak gerilimin ve dolayısıyla son enerjinin sıfır olması yalnızca Q₁ = Q₂ ise gerçekleşir.'),
  ('Bir Wheatstone sığaç köprüsünde sol üstte C₁, sol altta C₂, sağ üstte C₃, sağ altta C₄ sığaçları ve orta düğümler arasında C₅ sığacı bulunmaktadır. Giriş-çıkış uçlarına gerilim uygulandığında C₅ sığacının hiç yük tutmaması (üzerindeki gerilimin sıfır olması) hangi koşula bağlıdır?', 'C₁ · C₄ = C₂ · C₃ eşitliğinin sağlanmasına', ['C₁ + C₄ = C₂ + C₃ eşitliğinin sağlanmasına', 'C₅ sığasının diğer dört sığanın toplamına eşit olmasına', 'Tüm sığaçların mutlaka birbirinden farklı değerde olmasına'], 'Orta düğümlerin potansiyellerinin eşit olması için üst ve alt kollardaki gerilim bölme oranları eşit olmalıdır; bu da C₁/C₃ = C₂/C₄ yani çapraz çarpımların eşitliği C₁·C₄ = C₂·C₃ demektir.'),
  ('Sabit V gerilimli üretece bağlı paralel K ve L sığaçlarından K\'nin levhaları arası uzaklık yarıya indirilirse, L sığacının yükü (Ql) ve üreteçten çekilen toplam yük (Q_top) nasıl değişir?', 'L\'nin yükü değişmez, devrenin toplam yükü artar', ['L\'nin yükü azalır, devrenin toplam yükü değişmez', 'L\'nin yükü de devrenin toplam yükü de artar', 'L\'nin yükü artar, devrenin toplam yükü azalır'], 'K ve L paralel olduğundan L\'nin uçlarındaki gerilim doğrudan üreteç gerilimi V\'dir ve C_l değişmediğinden Ql = C_l·V sabit kalır. C_k iki katına çıktığından Qk artar ve Q_top = Qk + Ql artar.'),
  ('Bir doğru akım devresinde R direnci ile yüksüz C sığacı birbirine seri bağlanıp anahtar kapatıldığı anda (t = 0⁺) ve çok uzun süre geçtikten sonra (t → ∞) sığacın davranışı hangi devre elemanlarına benzetilebilir?', 'İlk anda düz iletken tel (kısa devre), çok uzun süre sonra açık anahtar (açık devre) gibi davranır', ['İlk anda açık anahtar, çok uzun süre sonra düz iletken tel gibi davranır', 'Her iki durumda da sonsuz büyüklükte bir direnç gibi davranır', 'İlk anda üreteç, çok uzun süre sonra diyot gibi davranır'], 't = 0⁺ anında yüksüz sığacın gerilimi Vc = Q/C = 0 olduğundan kısa devre gibi davranır; tamamen dolduğunda akımı kestiği için açık devre gibi davranır.'),
  ('Elinde çok sayıda özdeş 10 µF / 50 V değerinde sığaç bulunan bir teknisyen, 150 V gerilim altında çalışabilecek ve eşdeğer sığası yine 10 µF olacak bir sığaç bloğu kurmak istiyor. En az kaç adet özdeş sığaç kullanmalı ve nasıl bağlamalıdır?', 'Her birinde 3 sığacın seri olduğu 3 paralel kol kurarak toplam 9 sığaç kullanmalıdır', ['3 sığacı yalnızca seri bağlayarak toplam 3 sığaç kullanmalıdır', 'Her birinde 2 sığacın seri olduğu 3 paralel kol kurarak toplam 6 sığaç kullanmalıdır', '3 sığacı yalnızca paralel bağlayarak toplam 3 sığaç kullanmalıdır'], '150 V\'a dayanması için her kolda en az 150/50 = 3 özdeş sığaç seri olmalıdır. Bir seri kolun sığası 10/3 µF\'a düşer; tekrar 10 µF elde etmek için bu koldan 3 tanesi paralel bağlanmalıdır: 3 × 3 = 9 sığaç.'),
  ('Bir devrede doğru akım üretecine paralel bağlı bir lamba ve lambaya seri bağlı bir sığaç kolu ile lambaya paralel bağlı ikinci bir lamba kolu bulunmaktadır. Anahtar kapatıldığında lambaların ışık verme süreleri nasıl değerlendirilir?', 'Sığaca seri olan lamba sığaç dolana kadar anlık yanıp sönerken, üretece doğrudan paralel koldaki lamba sürekli ışık verir', ['Her iki lamba da sığaç dolana kadar yanar ve sonra tamamen söner', 'Sığaca seri olan lamba sürekli yanar, diğer lamba hiç ışık vermez', 'Doğru akımda sığaç üzerinden hiç yük geçmeyeceği için sığaca seri lamba ilk anda bile yanmaz'], 'Doğru akımda sığaç dolarken kısa süreli şarj akımı geçer ve seri lambayı anlık yakar; dolunca o koldaki akım kesilir. Bağımsız paralel koldaki lamba ise üreteç bitene dek yanar.'),
  ('Üretece bağlı paralel levhalı bir sığacın levhaları arasına dielektrik katsayısı daha büyük bir yalıtkan sokulurken sığacın sığası (C), yükü (Q) ve potansiyel farkı (V) niceliklerinden hangileri artar?', 'Sığa (C) ve yük (Q) artar, potansiyel farkı (V) sabit kalır', ['Yalnızca sığa (C) artar, yük ve potansiyel farkı sabit kalır', 'Sığa (C) ve potansiyel farkı (V) artar, yük sabit kalır', 'Yalnızca potansiyel farkı (V) artar, sığa ve yük azalır'], 'Üreteç V\'yi sabit tutar; yalıtkan C = κε₀A/d\'yi artırır ve Q = C·V gereği sığaçta biriken yük de artar.'),
  ('Yüklü ve üreteçten ayrılmış paralel levhalı bir sığacın levhalarının birbirine bakan ortak alanı (d sabit tutularak) küçültülürse sığacın potansiyel farkı (V) ve depoladığı enerji (U) nasıl değişir?', 'Hem potansiyel farkı hem de depolanan enerji artar', ['Hem potansiyel farkı hem de depolanan enerji azalır', 'Potansiyel farkı artar, depolanan enerji değişmez', 'Potansiyel farkı azalır, depolanan enerji artar'], 'Üreteçten ayrı olduğu için Q sabittir. Ortak alan A küçülünce C azalır; bu nedenle V = Q/C artar ve U = Q²/(2C) artar.'),
  ('Üst kolda seri bağlı 8 µF ve 8 µF, orta kolda tek başına 6 µF, alt kolda seri bağlı 3 µF ve 6 µF sığaçlarından oluşan üç paralel kolun eşdeğer sığası kaç µF\'dır?', '12 µF', ['10 µF', '16 µF', '8 µF'], 'Üst kol: (8×8)/(8+8) = 4 µF. Orta kol: 6 µF. Alt kol: (3×6)/(3+6) = 2 µF. Üç paralel kolun toplamı C_eş = 4 + 6 + 2 = 12 µF bulunur.'),
  ('Sığaları C₁ = 5 µF ve C₂ = 15 µF olan paralel bağlı iki sığaç grubuna toplam 80 µC yük verildiğinde C₂ = 15 µF\'lık sığaçta biriken yük kaç µC olur?', '60 µC', ['20 µC', '40 µC', '75 µC'], 'Paralel bağlı sığaçlar yükü sığalarıyla doğru orantılı paylaşır: Q₂ = Q_top · [C₂ / (C₁ + C₂)] = 80 × (15 / 20) = 60 µC olur.'),
  ('Seri bağlı C₁ = 4 µF ve C₂ = 8 µF sığaçlarından oluşan devreye bir doğru akım gerilimi uygulandığında C₁ sığacının uçları arasındaki gerilim 24 V oluyor. Buna göre devrenin toplam uçları arasındaki gerilim kaç V\'tur?', '36 V', ['48 V', '72 V', '32 V'], 'Q = C₁·V₁ = 4 µF × 24 V = 96 µC (seri olduğundan C₂\'nin yükü de 96 µC\'dur). V₂ = Q / C₂ = 96 / 8 = 12 V. Toplam gerilim V_top = 24 + 12 = 36 V bulunur.'),
  ('Sığası 9 µF olan bir sığaç 20 V\'luk üreteçle doldurulup ayrıldıktan sonra yüksüz C_x sığacına paralel bağlandığında ortak potansiyel 12 V oluyor. Buna göre C_x sığacının sığası kaç µF\'dır?', '6 µF', ['15 µF', '4,5 µF', '12 µF'], 'İlk yük Q = 9 × 20 = 180 µC. Ortak potansiyel V_ort = 180 / (9 + C_x) = 12 => 9 + C_x = 15 => C_x = 6 µF elde edilir.'),
  ('Bir RC şarj devresinde direnç R = 200 kΩ ve sığaç C = 25 µF olarak seçilmiştir. Bu devrenin zaman sabiti (τ = R·C) kaç saniyedir?', '5 saniye', ['0,5 saniye', '50 saniye', '8 saniye'], 'Zaman sabiti τ = R · C = (200 × 10³ Ω) × (25 × 10⁻⁶ F) = 5000 × 10⁻³ s = 5 s bulunur.'),
  ('Boşluktaki sığası 8 µF olan paralel levhalı bir sığaç 25 V\'luk üretece bağlıyken levhalar arası uzaklık iki katına çıkarılıp aynı anda levhalar arası κ = 5 olan yalıtkanla tamamen dolduruluyor. Son durumda sığaçta depolanan enerji kaç mJ olur?', '6,25 mJ', ['2,5 mJ', '12,5 mJ', '5 mJ'], 'Yeni sığa C\' = κ · C₀ / 2 = 5 × 8 / 2 = 20 µF olur. Üretece bağlı olduğundan V = 25 V kalır. Son enerji E = (1/2) · 20×10⁻⁶ · 25² = 10⁻⁵ × 625 = 6,25×10⁻³ J = 6,25 mJ bulunur.'),
  ('Özdeş iki sığaçtan K hava ortamında, L ise levhaları arası tamamen camla (κ > 1) dolu olacak biçimde birbirine paralel bağlanıp bir üreteçle yükleniyor. Üreteç bağlıyken K ve L sığaçlarının levhaları arasındaki elektrik alan şiddetleri (Ek, El) ve yükleri (Qk, Ql) arasındaki ilişki nasıldır?', 'Elektrik alan şiddetleri eşittir (Ek = El), L\'nin yükü daha büyüktür (Ql > Qk)', ['L\'nin elektrik alanı daha küçüktür (El < Ek), yükleri eşittir (Qk = Ql)', 'L\'nin hem elektrik alanı hem de yükü K\'ninkinden büyüktür', 'Elektrik alanları da yükleri de birbirine eşittir'], 'İkisi de aynı V gerilimine paralel bağlı ve levha aralıkları d özdeş olduğundan E = V/d her ikisinde de eşittir! Camlı olan L\'nin sığası κ kat büyük olduğundan Ql = Cl·V > Qk olur.'),
  ('Özdeş boyutlu iki düzlem sığaçtan X\'in içi hava, Y\'nin içi tamamen porselen (κ = 6) doludur. Bu iki sığaç birbirine seri bağlanıp bir üretece takıldığında levhaları arasındaki elektrik alan büyüklüklerinin oranı (Ex / Ey) kaç olur?', '6', ['1/6', '1', '36'], 'Seri bağlı olduklarından yükleri Q ve levha alanları A eşittir. Elektrik alan E = V/d = Q/(C·d) = Q/(κε₀A) bağıntısına göre κ ile ters orantılıdır: Ex / Ey = κ_y / κ_x = 6 / 1 = 6 bulunur.'),
  ('Aynı maddeden yapılmış içi dolu iletken X küresinin yarıçapı 2r, içi boş iletken Y küresel kabuğunun dış yarıçapı da 2r\'dir. Birbirinden çok uzakta bulunan bu iki iletkenin elektrik sığaları (Cx ve Cy) karşılaştırıldığında hangisi doğrudur?', 'İç kısım elektrik alanı sıfır olduğundan dış yarıçapları eşit olan iki küresel iletkenin sığaları eşittir (Cx = Cy)', ['X küresinin kütlesi ve hacmi daha fazla olduğu için sığası daha büyüktür (Cx > Cy)', 'Y küresinin iç yüzeyinde de yük birikeceği için sığası iki kat büyüktür (Cy = 2Cx)', 'İçi boş kürenin sığası sıfır, içi dolu kürenin sığası pozitif bir değerdir'], 'Durgun elektrostatikte yük yalnızca iletkenin dış yüzeyinde toplanır; dolayısıyla yalıtılmış küresel bir iletkenin sığası yalnız dış yarıçapına (C = 4πε₀R) bağlıdır ve iç yapısından bağımsızdır.'),
  ('Bir elektronik devrede besleme hattındaki ani gerilim dalgalanmalarını süzmek (filtrelemek) için yük direncine paralel bağlanan "filtre sığacının" sığa değeri nasıl seçilmelidir?', 'Gerilim değişimlerine karşı çıkış gerilimini uzun süre sabit tutabilmesi için zaman sabiti (R·C) dalgalanma periyodundan çok büyük olacak şekilde yüksek sığalı seçilmelidir', ['Hattan hiç yük çekmemesi için olabildiğince küçük (pikofarad mertebesinde) seçilmelidir', 'Yük direncini kısa devre etmesi için dielektrik dayanımı besleme geriliminden daha düşük seçilmelidir', 'Yalnızca yük direncine seri bağlanmalı ve sığası sıfıra yakın tutulmalıdır'], 'Filtre (tampon) sığacı gerilim yükseldiğinde yük depolayıp gerilim düştüğünde yüke akım sağlar; dalgalanmayı (ripple) küçük tutmak için τ = R_yük·C süresinin periyottan çok büyük olması, yani C\'nin büyük seçilmesi gerekir.'),
  ('Faraday indüksiyon yasasına göre ideal bir transformatörün hem birincil hem de ikincil sargılarında tek bir sarıma düşen indüksiyon elektromotor kuvvetleri için ne söylenebilir?', 'Her iki sargıda da tek sarım başına düşen gerilim birbirine eşittir', ['Çok sarımlı bobinde tek sarım başına düşen gerilim daha büyüktür', 'Az sarımlı bobinde tek sarım başına düşen gerilim daha büyüktür', 'Aralarındaki oran çekirdeğin özdirencine bağlı olarak değişir'], 'Ortak demir çekirdekte aynı manyetik akı değişimi her iki bobinin her sarımından geçtiğinden V_p / N_p = V_s / N_s = dΦ/dt eşitliği sağlanır.'),
  ('İdeal bir transformatörün primerinde 600 sarım, sekonderinde 150 sarım vardır. Sekonder uçlarına bağlanan 10 ohm\'luk saf dirençten 4 A etkin akım geçtiğine göre primer sargıdan çekilen etkin akım kaç A olur?', '1 A', ['16 A', '2 A', '0,5 A'], 'İdeal transformatörde I_p / I_s = N_s / N_p bağıntısından I_p = 4 · (150 / 600) = 1 A bulunur.'),
  ('Sarım sayıları N_p = 500 ve N_s = 2000 olan ideal bir transformatörün primerine 50 V etkin alternatif gerilim uygulanıyor. Sekonder uçlarına 400 ohm\'luk bir direnç bağlanırsa primerden çekilen etkin akım kaç A olur?', '2 A', ['0,5 A', '1 A', '4 A'], 'Önce V_s = 50 · (2000 / 500) = 200 V bulunur. Sekonder akımı I_s = 200 / 400 = 0,5 A olur. İdeal güç eşitliğinden I_p = 0,5 · (200 / 50) = 2 A elde edilir.'),
  ('Bir transformatörün sekonder devresindeki açık anahtar kapatılıp bir direnç devreye alındığında primer sargının şebekeden daha fazla akım çekmeye başlamasının fiziksel mekanizması nedir?', 'Sekonder akımının oluşturduğu zıt manyetik akının primerdeki zıt emk\'yı azaltması', ['Sekonder devrenin kapanmasıyla demir çekirdeğin kütlesel özdirencinin düşmesi', 'Primer sargıdaki sarım sayısının elektriksel yüklenmeyle kendiliğinden artması', 'Alternatif gerilim kaynağının frekansının yük direnciyle doğru orantılı yükselmesi'], 'Lenz yasasına göre sekonder akımı çekirdekte zıt yönlü akı üretir; bunu dengelemek ve ortak akıyı korumak için primer sargı kaynaktan ek akım çeker.'),
  ('Sekonder uçları açık bırakılan (yüksüz çalışan) ideal bir transformatörün primer sargısından geçen akım ve harcanan ortalama güç için hangisi doğrudur?', 'Yalnızca küçük bir mıknatıslama akımı geçer ve net aktif güç sıfırdır', ['Primer sargı kısa devre gibi davranarak sonsuz büyüklükte güç çeker', 'Sekonder açık olduğundan primerde hiç manyetik alan çizgisi oluşmaz', 'Primer akımı gerilimle aynı fazda kalarak çekirdeği hızla eritir'], 'İdeal yüksüz transformatör saf indüktör gibi davranır; akım ile gerilim arasında 90 derece faz farkı olduğundan ortalama aktif güç harcanmaz.'),
  ('Birbirine seri bağlı K ve L ideal transformatörlerinden K\'nin sarım sayıları 200 ve 600, L\'nin sarım sayıları ise 900 ve 300\'dür. K\'nin girişine 120 V alternatif gerilim uygulanırsa L\'nin çıkışından kaç V gerilim alınır?', '120 V', ['360 V', '40 V', '1080 V'], 'K transformatörü gerilimi 120 · (600 / 200) = 360 V değerine yükseltir. Bu gerilim L\'nin girişine doğrudan uygulanır ve çıkışta 360 · (300 / 900) = 120 V alınır.'),
  ('Ardışık bağlanmış X ve Y transformatörlerinde sarım sayıları sırasıyla N_1 = 100, N_2 = 400, N_3 = 200 ve N_4 = 600\'dür. X\'in girişine 25 V alternatif gerilim uygulandığında Y\'nin çıkış gerilimi kaç V olur?', '300 V', ['100 V', '75 V', '150 V'], 'Ardışık transformatörlerde ara bağlantı gerilimi korunur (V_2 = V_3). Toplam oran V_4 / V_1 = (N_2 / N_1) · (N_4 / N_3) = 4 · 3 = 12 olup V_4 = 25 · 12 = 300 V bulunur.'),
  ('Ardışık bağlı X ve Y transformatörlerinde X\'in çıkış sargısı (N_2 sarımlı) ile Y\'nin giriş sargısı (N_3 sarımlı) birbirine iletken tellerle bağlanmıştır. Çıkış gerilimini artırmak için hangi işlem tek başına yapılmalıdır?', 'N_2 veya N_4 sarım sayısını artırmak', ['N_1 veya N_3 sarım sayısını artırmak', 'N_2 ve N_3 sarım sayılarını aynı oranda azaltmak', 'Yalnızca ara bağlantı tellerinin uzunluğunu iki katına çıkarmak'], 'V_çıkış = V_giriş · (N_2 · N_4) / (N_1 · N_3) bağıntısına göre N_2 veya N_4 artırıldığında çıkış gerilimi yükselir.'),
  ('Ortak bir demir çekirdeğin sol kolunda 300 sarımlı primer bobin, sağ kolunda ise birbirinden bağımsız 150 sarımlı K ve 450 sarımlı L sekonder bobinleri vardır. Primere 180 V alternatif gerilim uygulanırsa K ve L\'nin etkin gerilimleri sırasıyla kaç V olur?', '90 V ve 270 V', ['360 V ve 120 V', '60 V ve 180 V', '90 V ve 180 V'], 'Aynı çekirdekte her sekonder bobin primerle kendi sarım oranında gerilim üretir: V_K = 180 · (150 / 300) = 90 V ve V_L = 180 · (450 / 300) = 270 V.'),
  ('Tek primerli ve iki ayrı sekonder sargılı ideal bir transformatörde primer gücü P_p, birinci sekonder gücü P_1 ve ikinci sekonder gücü P_2 ise bu büyüklükler arasındaki bağıntı nedir?', 'P_p = P_1 + P_2', ['P_p = (P_1 · P_2) /', 'P_p = |P_1 - P_2|', 'P_p = 2 ·'], 'Enerjinin korunumu gereği ideal bir transformatörde primerden çekilen toplam güç, tüm sekonder sargılarda harcanan güçlerin toplamına eşittir.'),
  ('Primer sargısı 800 sarımlı ideal bir transformatöre 160 V alternatif gerilim uygulanıyor. Aynı çekirdekteki 200 sarımlı birinci sekondere 20 ohm, 400 sarımlı ikinci sekondere 80 ohm direnç bağlanırsa primerden çekilen toplam akım kaç A olur?', '1 A', ['4 A', '2 A', '0,5 A'], 'Birinci sekonderde V_1 = 160·(200/800) = 40 V olup P_1 = 40²/20 = 80 W; ikinci sekonderde V_2 = 160·(400/800) = 80 V olup P_2 = 80²/80 = 80 W harcanır. Toplam güç 160 W olduğundan I_p = 160 / 160 = 1 A bulunur.'),
  ('Yükseltici bir ideal transformatörün giriş gerilimi 110 V, çıkış gerilimi 550 V\'tur. Sekonder sargısına bağlı yükten 1,2 A etkin akım geçtiğine göre primer sargıdan çekilen etkin akım kaç A olur?', '6 A', ['0,24 A', '3 A', '12 A'], 'İdeal güç eşitliğinden I_p = I_s · (V_s / V_p) = 1,2 · (550 / 110) = 1,2 · 5 = 6 A bulunur.'),
  ('Primer sargısı 500 sarımlı ideal bir transformatör 100 V alternatif gerilim kaynağına bağlıdır. Sekonder sargıdan 40 sarım sökülüp çıkarıldığında çıkış etkin geriliminin kaç V azaldığı görülür?', '8 V', ['4 V', '12,5 V', '20 V'], 'Birim sarım başına düşen gerilim V_p / N_p = 100 / 500 = 0,2 V/sarım\'dır. Sekonderden 40 sarım eksildiğinde çıkış gerilimi 40 · 0,2 = 8 V azalır.'),
  ('Primer sargısından 20 sarım eksiltildiğinde aynı 120 V giriş gerilimi altında çıkış gerilimi 60 V\'tan 75 V\'a yükselen ideal bir transformatörün başlangıçtaki primer sarım sayısı kaçtır?', '100', ['80', '120', '60'], 'Sekonder sarımı ve giriş gerilimi sabitken V_s primer sarımıyla ters orantılıdır: N_p / (N_p - 20) = 75 / 60 = 5 / 4 yazılır; 4N_p = 5N_p - 100 eşitliğinden N_p = 100 bulunur.'),
  ('Bir transformatörün birincil sargısına etkin değeri 100 V olan alternatif gerilim yerine 100 V\'luk sabit doğru gerilim yanlışlıkla bağlandığında birincil sargının yanma tehlikesi geçirmesinin nedeni nedir?', 'Doğru akımda zıt indüksiyon emk\'sı oluşmadığından akımı yalnızca küçük ohmik tel direncinin sınırlaması', ['Doğru akımın bakır telin özdirencini anında bin katına çıkararak yalıtımı delmesi', 'Sekonder sargıda oluşan sonsuz gerilimin primer sargıya kıvılcım olarak atlaması', 'Demir çekirdeğin doğru akımda nükleer bozunmaya uğrayarak aşırı ısı yayması'], 'Alternatif akımda akımı büyük ölçüde indüktif reaktans (zıt emk) sınırlar; doğru akımda sürekli durumda indüktif reaktans sıfırdır ve sargının birkaç ohm\'luk saf direnci aşırı akım çeker.'),
  ('Primeri 1000 sarımlı ideal bir transformatöre 200 V etkin gerilim uygulanmaktadır. Sekonderdeki 500 sarımlı K bobinine 50 ohm, 250 sarımlı L bobinine 25 ohm direnç bağlandığında primerden çekilen toplam etkin akım kaç A olur?', '1,5 A', ['3 A', '0,75 A', '2,5 A'], 'V_K = 200·(500/1000) = 100 V olup P_K = 100²/50 = 200 W; V_L = 200·(250/1000) = 50 V olup P_L = 50²/25 = 100 W bulunur. Toplam güç 300 W olduğundan I_p = 300 / 200 = 1,5 A elde edilir.'),
  ('Bir transformatörün sekonderinde aynı yönde sarılmış 200 sarımlı X ve 120 sarımlı Y bobinleri seri bağlanarak uçlarından toplam gerilim alınıyor. Sarımlar zıt yönlü bağlanacak biçimde uçlar yer değiştirirse çıkış etkin gerilimi nasıl değişir?', '320 sarıma karşılık gelen değerden 80 sarıma karşılık gelen değere düşer', ['320 sarıma karşılık gelen değerden 240 sarıma karşılık gelen değere düşer', 'Zıt bağlantı manyetik alanı tamamen yok edeceğinden sıfıra iner', 'Değişmez çünkü alternatif akımda sargı yönünün gerilime etkisi yoktur'], 'Aynı yönlü seri bağlantıda emk\'lar toplanırken (200+120=320 eşdeğer sarım), ters seri bağlantıda zıt fazlı emk\'lar birbirinden çıkarılır (200-120=80 eşdeğer sarım).'),
  ('Primeri 600 sarımlı bir transformatöre 120 V alternatif gerilim uygulanıyor. Sekonderde seri bağlı 250 sarımlı K ve 100 sarımlı L bobinleri zıt sarım yönlü bağlandığına göre açık uçlar arasındaki etkin gerilim kaç V olur?', '30 V', ['70 V', '50 V', '20 V'], 'Birim sarım başına gerilim 120 / 600 = 0,2 V/sarım olur. Zıt bağlı bobinlerin net etkin sarım farkı 250 - 100 = 150 olduğundan çıkış gerilimi 150 · 0,2 = 30 V bulunur.'),
  ('Elektrik kaynak makinelerinde kullanılan transformatörlerin sarım oranları nasıl seçilir ve bunun temel amacı nedir?', 'Çok sarımlı primer ve az sarımlı sekonder seçilerek düşük gerilimde çok yüksek akım elde etmek', ['Az sarımlı primer ve çok sarımlı sekonder seçilerek elektrot ucunda binlerce volt ark oluşturmak', 'Eşit sarımlı iki sargı kullanılarak şebeke akımını değiştirmeden yalnızca frekansı yükseltmek', 'Sekonder sargıyı ince ve çok turlu yaparak metalin soğuk birleştirilmesini sağlamak'], 'Metal eritmek için I²·R·t gereği çok yüksek akım (yüzlerce amper) gerekir; güvenlik için gerilim düşürülürken akım büyük oranda artırılır.'),
  ('Ampermetre penselerinin (pensampermetre) içinden geçen tek bir ana iletken teldeki alternatif akımı kabloyu kesmeden ölçmesi transformatör ilkesine dayanır. Ana iletken 1 sarımlı primer, alet içindeki halka bobin 500 sarımlı sekonder ise halka bobinden 0,04 A geçtiğinde ana teldeki akım kaç A\'dir?', '20 A', ['200 A', '2 A', '125 A'], 'Akım transformatörü bağıntısından I_p · N_p = I_s · N_s yazılır: I_p · 1 = 0,04 · 500 = 20 A bulunur.'),
  ('Yüksek akımlı hatlarda ölçü aletlerini korumak için kullanılan akım transformatörlerinin sekonder uçları, primerden akım geçerken kesinlikle açık devre bırakılmaz. Sekonder açık bırakılırsa ne gerçekleşir?', 'Dengeleyici sekonder akımı kesildiğinden tüm primer akımı çekirdeği doyuma sokar ve sekonderde çok yüksek tehlikeli gerilim indüklenir', ['Primer hattından geçen şebeke akımı anında sıfırlanarak bağlı olduğu fabrikanın enerjisini tamamen keser', 'Sekonder sargıdan sonsuz akım geçerek bağlı olmayan açık uçlar arasında soğuma etkisi yaratır', 'Demir çekirdeğin manyetik geçirgenliği sonsuza giderek sargı direncini tamamen ortadan kaldırır'], 'Sekonder açıkken zıt akı üreten I_s sıfır olur; primer akımının tamamı mıknatıslama akımı gibi davranarak keskin akı değişimleriyle sekonderde tehlikeli yüksek gerilim tepecikleri üretir.'),
  ('Sargıları 200 ve 800 sarımlı olan ideal bir transformatör önce 200 sarımlı ucundan 100 V alternatif gerilime bağlanarak V_1 çıkış gerilimi elde ediliyor. Ardından ters çevrilip 800 sarımlı ucundan aynı 100 V kaynağa bağlanarak V_2 çıkış gerilimi alınıyor. V_1 / V_2 oranı kaçtır?', '16', ['4', '8', '2'], 'İlk durumda yükseltici çalışır: V_1 = 100 · (800 / 200) = 400 V. İkinci durumda alçaltıcı çalışır: V_2 = 100 · (200 / 800) = 25 V. Oranları 400 / 25 = 16 bulunur.'),
  ('İdeal bir transformatörün sekonder sargısına bağlı ayarlı direncin (reosta) sürgüsü çekilerek direnç değeri yarıya indiriliyor. Primer gerilimi sabit tutulduğuna göre sekonder gerilimi (V_s) ve primer akımı (I_p) nasıl değişir?', 'V_s değişmez, I_p iki katına çıkar', ['V_s yarıya iner, I_p değişmez', 'V_s iki katına çıkar, I_p dört katına çıkar', 'V_s değişmez, I_p yarıya iner'], 'V_s yalnızca V_p ve sarım oranına bağlı olduğundan değişmez. R yarıya inince I_s = V_s / R iki katına çıkar; dolayısıyla I_p de iki katına çıkar.'),
  ('Primerine V_p(t) = 200√2 · sin(100πt) V gerilimi uygulanan ideal bir transformatörün sarım oranı N_s / N_p = 1/4\'tür. Sekondere 10 ohm saf direnç bağlandığında dirençte harcanan ortalama güç kaç W olur?', '250 W', ['500 W', '125 W', '1000 W'], 'Primer etkin gerilimi V_p = 200 V\'tur. Sekonder etkin gerilimi V_s = 200 · (1/4) = 50 V olur. Dirençteki ortalama güç P = V_s² / R = 50² / 10 = 250 W bulunur.'),
  ('Bir transformatörün girişine zamanla düzgün artan (doğrusal rampa biçimli, V = k·t) bir gerilim kısa bir süre boyunca uygulanırsa, doyuma ulaşmadan önce ideal sekonder sargı uçlarında nasıl bir gerilim gözlenir?', 'Sabit büyüklükte bir doğru gerilim', ['Zamanla parabolik olarak artan gerilim', 'Sürekli yön değiştiren sinüzoidal gerilim', 'Tamamen sıfır büyüklüğünde gerilim'], 'Primer gerilimi sabit hızla değişen bir akı (dΦ/dt = sabit) oluşturur; bu sabit akı türevi sekonderde sabit büyüklükte bir emk indükler.'),
  ('İdeal K transformatörünün sarım sayıları N_1 = 300, N_2 = 900; ona seri bağlı ideal L transformatörünün sarım sayıları N_3 = 600, N_4 = 200\'dür. L\'nin çıkışındaki yükten 6 A akım geçtiğine göre K\'nin girişinden çekilen akım kaç A\'dir?', '6 A', ['18 A', '2 A', '1 A'], 'Toplam gerilim oranı (900/300)·(200/600) = 3 · (1/3) = 1 olduğundan V_çıkış = V_giriş olur. İdeal sistemde P_giriş = P_çıkış eşitliğinden giriş akımı da 6 A\'dir.'),
  ('Ardışık bağlı iki ideal transformatörde sarım sayıları N_1 = 200, N_2 = 500, N_3 = 1000 ve N_4 = 400\'dür. Girişe 100 V alternatif gerilim uygulandığında ara bağlantı tellerindeki etkin gerilim ve en sondaki çıkış gerilimi sırasıyla kaç V olur?', '250 V ve 100 V', ['250 V ve 625 V', '40 V ve 100 V', '500 V ve 200 V'], 'Birinci transformatör çıkışı (ara hat gerilimi) V_2 = 100 · (500 / 200) = 250 V olur. İkinci transformatör çıkışı V_4 = 250 · (400 / 1000) = 100 V bulunur.'),
  ('Bir transformatörün çekirdeğinde hava boşluğu bulunması veya sargıların üst üste değil de birbirinden uzak yerleştirilmesi öncelikle hangi olumsuz duruma yol açar?', 'Kaçak manyetik akının artarak sekonderde indüklenen gerilimin beklenenden düşük kalmasına', ['Sekonder sargıdaki alternatif gerilim frekansının primer frekansından büyük olmasına', 'Primer sargı direncinin sıfırlanarak kaynaktan çekilen akımın tamamen durmasına', 'Doğru akım uygulandığında bile transformatörün sürekli yüksek verimle çalışmasına'], 'Hava boşluğu manyetik relüktansı (direnci) artırır; primerin ürettiği akının bir kısmı sekondere ulaşmadan havadan kapanır (akı kaçağı).'),
  ('Primer sarım sayısı N_p, sekonder sarım sayısı N_s olan ideal bir transformatörde N_p / N_s = 2/5\'tir. Primerden 15 A etkin akım çekildiğine göre sekonderden alınan etkin akım kaç A olur?', '6 A', ['37,5 A', '12 A', '3 A'], 'İdeal transformatörde akım sarım sayısıyla ters orantılıdır: I_s = I_p · (N_p / N_s) = 15 · (2 / 5) = 6 A bulunur.'),
  ('Bir laboratuvar deneyinde öğrenci, 6 V\'luk bir pil, bir anahtar, reosta ve bir transformatör kullanarak sekondere bağlı galvanometrede sürekli bir sapma elde etmeye çalışıyor. Hangi işlem süresince galvanometre ibresi sıfırdan farklı bir değer gösterir?', 'Anahtar kapalıyken reosta sürgüsü sürekli hareket ettirildiği sürece', ['Anahtar kapatıldıktan uzun süre sonra reosta sürgüsü sabit tutulduğunda', 'Pil ters çevrilip bağlandıktan sonra devre kararlı hale ulaştığında', 'Sekonder sargının sarım sayısı on katına çıkarılıp sabit akım verildiğinde'], 'Reosta sürgüsü hareket ettirildiğinde primerdeki doğru akım şiddeti değişir; bu değişim manyetik akıyı değiştirdiği için hareket süresince sekonderde emk indüklenir.'),
  ('Lenz yasasına göre bir transformatörün sekonder sargısında oluşan indüksiyon akımının yönü neye göre belirlenir?', 'Çekirdekte kendisini oluşturan manyetik akı değişimine karşı koyacak yönde', ['Primer sargıdaki akımla her an aynı dolanım yönünde olacak biçimde', 'Demir çekirdeğin sıcaklığını en hızlı artıracak manyetik alanı kuracak yönde', 'Yalnızca sekondere bağlanan yük direncinin geometrik boyutlarına bağlı olarak'], 'Lenz yasası gereği indüksiyon akımı, çekirdekteki manyetik akı artarken azaltıcı, azalırken destekleyici yönde manyetik alan oluşturur.'),
  ('Nokta kuralıyla işaretlenmiş ideal bir transformatörde primerin noktalı ucuna anlık olarak +100 V (diğer ucuna göre) uygulanmaktadır. Sarım oranı N_p : N_s = 5 : 2 olduğuna göre aynı anda sekonderin noktalı ucu diğer ucuna göre kaç V potansiyeldedir?', '+40 V', ['-40 V', '+250 V', '-250 V'], 'Nokta kuralına göre noktalı uçlar aynı anlık kutupluluğa sahiptir; büyüklük 100 · (2 / 5) = 40 V olduğundan sekonderin noktalı ucu +40 V olur.'),
  ('Primerine 240 V alternatif gerilim uygulanan ideal bir transformatörün sekonderinde 60 V gerilim ölçülüyor ve sekonderdeki lambanın gücü 30 W\'tır. Primer sargıdan geçen etkin akım kaç A\'dir?', '0,125 A', ['0,5 A', '2 A', '0,25 A'], 'İdeal transformatörde P_p = P_s = 30 W olduğundan I_p = P_p / V_p = 30 / 240 = 1/8 = 0,125 A bulunur.'),
  ('Bir transformatörün hem primer hem de sekonder sarım sayıları iki katına çıkarılıp aynı alternatif gerilim kaynağına ve aynı yük direncine bağlanırsa çıkış gerilimi ve çıkış gücü nasıl değişir?', 'Çıkış gerilimi de çıkış gücü de değişmez', ['Çıkış gerilimi iki katına çıkar, çıkış gücü dört katına çıkar', 'Çıkış gerilimi değişmez, çıkış gücü yarıya iner', 'Çıkış gerilimi dört katına çıkar, çıkış gücü iki katına çıkar'], 'N_s / N_p oranı (2N_s / 2N_p) değişmediğinden ideal transformatörde V_s sabit kalır; yük direnci aynı olduğundan P_s = V_s² / R de değişmez.'),
  ('Üç çıkış uçlu (K, L, M) bir sekonder bobinde K-L arası 120 sarım, L-M arası aynı yönde devam eden 180 sarımdır. 600 sarımlı primere 300 V alternatif gerilim uygulandığında K-M uçları arasındaki etkin gerilim kaç V olur?', '150 V', ['60 V', '90 V', '30 V'], 'K-M arasında aynı yönde toplam 120 + 180 = 300 sarım vardır. V_KM = 300 · (300 / 600) = 150 V bulunur.'),
  ('Sekonder sargısında sırasıyla X, Y, Z, T uçları bulunan bir transformatörde X-Y arası 50 sarım, Y-Z arası 100 sarım, Z-T arası 150 sarımdır (tümü aynı yönlü). 500 sarımlı primere 250 V uygulandığında 125 V gerilim elde etmek için yük hangi iki uç arasına bağlanmalıdır?', 'Y - T uçları arasına', ['X - Y uçları arasına', 'X - Z uçları arasına', 'Z - T uçları arasına'], 'Birim sarım gerilimi 250 / 500 = 0,5 V/sarım olur. 125 V için 125 / 0,5 = 250 sarım gerekir. Y-Z (100) ile Z-T (150) toplamı Y-T arasında 250 sarım verir.'),
  ('Primer sargısı 400 sarımlı ideal bir transformatörün girişine 80 V etkin alternatif gerilim uygulanıyor. Sekonderdeki özdeş iki lamba birbirine paralel bağlı olup her biri 20 V gerilimle 10 W güç harcadığına göre sekonder sarım sayısı ve primer akımı nedir?', '100 sarım ve 0,25 A', ['100 sarım ve 0,125 A', '1600 sarım ve 1 A', '200 sarım ve 0,5 A'], 'V_s = 20 V için N_s = 400 · (20 / 80) = 100 sarım olur. İki lamba toplam 20 W güç çeker; P_p = 20 W = 80 · I_p eşitliğinden I_p = 0,25 A bulunur.'),
  ('Bir transformatörün çekirdeği bakır veya alüminyum yerine yumuşak silisli çelikten üretilir. Bunun elektromanyetik kuplaj açısından birincil nedeni nedir?', 'Ferromanyetik çeliğin bağıl manyetik geçirgenliğinin bakır ve alüminyuma göre binlerce kat büyük olması', ['Çeliğin elektriksel iletkenliğinin bakırdan yüksek olup elektron geçişini hızlandırması', 'Bakır ve alüminyumun alternatif manyetik alanda hızla eriyerek sıvı hale geçmesi', 'Çeliğin yerin manyetik alanını tamamen perdeleyerek yerçekimi etkisini sıfırlaması'], 'Yumuşak ferromanyetik malzemelerin bağıl manyetik geçirgenliği çok yüksektir; böylece az bir mıknatıslama akımıyla güçlü ve sargılara kilitlenmiş bir manyetik akı elde edilir.'),
  ('Tıbbi cihazların bulunduğu ameliyathanelerde sarım oranı 1:1 (N_p = N_s) olan yalıtım (izolasyon) transformatörleri kullanılır. Gerilimi hiç değiştirmediği halde bu transformatörün kullanılma amacı nedir?', 'Sekonder devreyi toprak referanslı şebekeden elektriksel olarak ayırıp elektrik çarpması riskini azaltmak', ['Şebekeden gelen alternatif akımı ameliyat cihazları için tam doğru akıma dönüştürmek', 'Gerilimi sabit tutarken akımı on katına çıkararak cihazların daha parlak çalışmasını sağlamak', 'Şebeke frekansını insan vücudunun hissetmeyeceği ultrasonik düzeylere yükseltmek'], '1:1 izolasyon transformatörü çıkış hattının toprakla doğrudan bağlantısını keser; hasta veya personel tek bir iletkene dokunsa bile toprak üzerinden devre tamamlanmadığından çarpılma önlenir.'),
  ('Primer gerilimi 150 V olan ideal bir transformatörde primer sarım sayısı sekonder sarım sayısının 3 katıdır. Sekondere bağlanan direnç 25 ohm olduğuna göre bu dirençte 10 saniyede açığa çıkan ısı enerjisi kaç Joule\'dür?', '1000 J', ['3000 J', '100 J', '9000 J'], 'V_s = 150 / 3 = 50 V olur. Direnç gücü P = V_s² / R = 2500 / 25 = 100 W bulunur. 10 saniyede E = P · t = 100 · 10 = 1000 J ısı açığa çıkar.'),
  ('Bir transformatörün sargılarında kullanılan bakır tellerin dış yüzeyinin ince vernik (emaye) tabakasıyla kaplanmasının nedeni nedir?', 'Üst üste ve yan yana sarılan sarımların birbirine temas ederek kısa devre olmasını önlemek', ['Bakır telin içinden geçen manyetik alan çizgilerini telin içine hapsetmek', 'Alternatif akımın tel yüzeyinden havaya ışık enerjisi olarak yayılmasını engellemek', 'Sargı direncini artırarak primerden geçen akımı sıfıra yakın tutmak'], 'Çıplak bakır tel sarılırsa tüm turlar birbirine değerek tek bir kalın halka gibi kısa devre olur ve hedeflenen sarım sayısı (N) işlevini yitirir.'),
  ('Bir transformatörün primer sargısından 2 A etkin akım geçerken sekonder sargısından 5 A etkin akım geçtiği ölçülüyor. Yalnızca bu ölçüme dayanarak transformatör hakkında ideal olmasa bile hangisi kesinlikle doğrudur?', 'Alçaltıcı bir transformatördür ve sekonder gerilimi primer geriliminden küçüktür', ['Yükseltici bir transformatördür ve sekonder sarım sayısı daha fazladır', 'Verimi %100\'den büyüktür çünkü çıkış akımı giriş akımını aşmıştır', 'Sekonder sargıdaki alternatif akımın frekansı primerin 2,5 katıdır'], 'Gerçek transformatörde P_s ≤ P_p olduğundan V_s · 5 ≤ V_p · 2 yani V_s ≤ 0,4 · V_p olmalıdır; dolayısıyla kesinlikle gerilim düşürücü (alçaltıcı) olarak çalışmaktadır.'),
  ('Verimi %75 olan gerçek bir transformatörün primer sargısına 240 V etkin gerilim uygulandığında primerden 5 A akım geçmektedir. Sekonder gerilimi 180 V olarak ölçüldüğüne göre sekonderden alınan akım kaç A\'dir (yük saf dirençtir)?', '5 A', ['6,67 A', '4 A', '3,75 A'], 'P_p = 240 · 5 = 1200 W. Verim %75 olduğundan P_s = 1200 · 0,75 = 900 W olur. I_s = P_s / V_s = 900 / 180 = 5 A bulunur.'),
  ('Verimi %80 olan bir transformatörün sekonder uçlarına bağlı 20 ohm\'luk saf dirençten 3 A etkin akım geçmektedir. Primer uçlarındaki etkin gerilim 150 V olduğuna göre primerden çekilen etkin akım kaç A olur?', '1,5 A', ['1,2 A', '2 A', '0,96 A'], 'Sekonder gücü P_s = I_s² · R = 9 · 20 = 180 W\'tır. η = P_s / P_p = 0,80 olduğundan P_p = 180 / 0,80 = 225 W bulunur. I_p = 225 / 150 = 1,5 A elde edilir.'),
  ('Gerçek (ideal olmayan) bir transformatörde sekonder devre yüklüyken sarım sayıları, gerilimler ve akımlar arasındaki genel ilişki için hangisi doğrudur?', 'Gerilim oranı sarım oranına yaklaşık eşitken çıkış gücü giriş gücünden küçüktür', ['Akım oranı sarım oranıyla doğru orantılıyken çıkış gücü giriş gücünden büyüktür', 'Verim düştükçe sekonderden alınan güç primerden çekilen gücü aşmaya başlar', 'Kayıplar yalnızca frekansı düşürür, giriş ve çıkış güçlerinin eşitliğini bozmaz'], 'Gerçek transformatörlerde az miktarda sargı gerilim düşümü olsa bile V_p/V_s ≈ N_p/N_s yaklaşımı genellikle kullanılır; ancak ısı kayıpları yüzünden V_s·I_s < V_p·I_p olur.'),
  ('Sarım oranı N_p / N_s = 4 olan ve gerilimlerin sarım sayılarıyla tam orantılı kabul edildiği %90 verimli bir transformatörde primer akımı 2,5 A ise sekonder akımı kaç A olur?', '9 A', ['10 A', '8 A', '11,1 A'], 'V_p / V_s = N_p / N_s = 4\'tür. Verim bağıntısı η = (V_s · I_s) / (V_p · I_p) = (1/4) · (I_s / 2,5) = 0,90 yazılır; buradan I_s = 0,90 · 10 = 9 A bulunur.'),
  ('Gerilimlerin sarım sayılarıyla orantılı olduğu gerçek bir transformatörde N_p = 600, N_s = 1200\'dür. Verimi %85 olan bu transformatörün sekonderinden 3,4 A akım çekildiğinde primer sargıdan geçen akım kaç A olur?', '8 A', ['6,8 A', '5,78 A', '10 A'], 'V_s / V_p = 1200 / 600 = 2\'dir. η = (V_s · I_s) / (V_p · I_p) ⇒ 0,85 = 2 · (3,4 / I_p) = 6,8 / I_p yazılır; buradan I_p = 6,8 / 0,85 = 8 A bulunur.'),
  ('Gerçek transformatörlerde karşılaşılan "bakır kayıpları" ifadesi fiziksel olarak hangi enerji dönüşümünü tanımlar?', 'Primer ve sekonder sargı tellerinin ohmik direnci nedeniyle I²·R biçiminde açığa çıkan Joule ısısını', ['Demir çekirdeğin içindeki manyetik bölgelerin yön değiştirirken tükettiği enerjiyi', 'Transformatör kazanındaki soğutma yağının buharlaşarak kütlesinin azalmasını', 'Bakır atomlarının alternatif manyetik alanda radyoaktif ışıma yaparak bozunmasını'], 'Sargılar bakır (veya alüminyum) iletkenden yapıldığı için üzerlerinden geçen akımın tel direnciyle oluşturduğu I_p²·R_p + I_s²·R_s ısı kaybına bakır kaybı denir.'),
  ('Transformatör çekirdeğinde alternatif akımın her periyodunda atomik manyetik dipollerin (domenlerin) sürekli ters yönde dizilmeye zorlanması sırasında iç sürtünme benzeri etkiyle oluşan ısı kaybına ne ad verilir?', 'Histerezis (manyetik gecikme) kaybı', ['Kapasitif dielektrik sızıntı kaybı', 'Korona deşarjı iyonlaşma kaybı', 'Peltier termoelektrik soğuma kaybı'], 'Ferromanyetik malzemenin mıknatıslanma-mıknatıssızlanma döngüsünde B-H eğrisi içinde kalan alanla orantılı olarak ısıya dönüşen enerjiye histerezis kaybı denir.'),
  ('Bir transformatör çekirdeğinde histerezis kayıplarını azaltmak için malzeme seçiminde hangi manyetik özelliğe sahip ferromanyetik alaşım tercih edilmelidir?', 'Histerezis döngüsü dar ve kalıcı mıknatıslanması (koersitif alanı) düşük yumuşak manyetik malzeme', ['Histerezis döngüsü çok geniş ve kalıcı mıknatıslanması yüksek sert mıknatıs çeliği', 'Bağıl manyetik geçirgenliği birden küçük olan diyamanyetik bizmut alaşımı', 'Mıknatıslanma yönünü hiç değiştirmeyen önceden kutuplanmış sabit neodimyum mıknatıs'], 'Sabit mıknatıs yapımının aksine transformatörlerde kolay mıknatıslanıp kolayca mıknatıslığını bırakan (dar B-H ilmekli) yumuşak silisli çelik kullanılır.'),
  ('Bir elektrik santralinden üretilen 10 MW (10⁷ W) sabit güç, toplam direnci 5 ohm olan iletim hattıyla şehre taşınacaktır. İletim gerilimi 100 kV (10⁵ V) seçilirse hatta birim zamanda ısıya dönüşen kayıp güç kaç kW olur (cosφ = 1)?', '50 kW', ['500 kW', '5 kW', '200 kW'], 'Hattan geçen akım I = P / V = 10⁷ / 10⁵ = 100 A olur. Hattaki ısı kaybı P_kayıp = I² · R = 100² · 5 = 50.000 W = 50 kW bulunur.'),
  ('Toplam direnci 4 ohm olan bir enerji nakil hattından şehre 2 MW (2·10⁶ W) güç iletilmektedir. İletim gerilimi 20 kV yerine yükseltici transformatörle 200 kV değerine çıkarılırsa hattaki ısı kaybı gücü kaç W\'tan kaç W\'a düşer?', '40.000 W\'tan 400 W\'a düşer', ['40.000 W\'tan 4.000 W\'a düşer', '80.000 W\'tan 8.000 W\'a düşer', '20.000 W\'tan 200 W\'a düşer'], '20 kV için I_1 = 2·10⁶ / 2·10⁴ = 100 A ve P_k1 = 100² · 4 = 40.000 W. 200 kV için I_2 = 10 A ve P_k2 = 10² · 4 = 400 W olur (100 kat azalır).'),
  ('Sabit bir P elektriksel gücünün R dirençli aynı iletim hattı üzerinden taşınması sırasında iletim gerilimi V katına (örneğin n katına) çıkarılırsa, iletim tellerinde birim zamanda ısıya dönüşen kayıp güç hangi oranda değişir?', '1 / n² oranında azalır', ['1 / n oranında azalır', 'n katına çıkar', 'n² katına çıkar'], 'Hat akımı I = P / V olduğundan V değeri n katına çıktığında I değeri 1/n\'e iner. Kayıp güç P_kayıp = I² · R = (P² · R) / V² bağıntısı gereği 1/n² oranında azalır.'),
  ('Büyük güçlü şebeke transformatörlerinin sargı ve çekirdeklerinin içi özel mineral yağ ile dolu çelik kazanlar içine yerleştirilmesinin iki temel mühendislik amacı nedir?', 'Isıyı konveksiyonla dış yüzey kanatçıklarına taşıyarak soğutma sağlamak ve yüksek gerilim yalıtımını güçlendirmek', ['Demir çekirdeğin paslanmasını hızlandırarak manyetik geçirgenliği artırmak ve sargı direncini büyütmek', 'Alternatif akımın frekansını sıvı viskozitesiyle düşürmek ve Fuko akımlarını yağ içinde toplamak', 'Yağın elektriksel iletkenliğinden yararlanarak primer ve sekonder arasında ek akım köprüsü kurmak'], 'Trafo yağı hem mükemmel bir elektriksel yalıtkandır (dielektrik dayanımı yüksektir) hem de sargı/çekirdek ısısını radyatör peteklerine taşıyan etkili bir soğutucudur.'),
  ('Şehir içi trafo merkezlerinin yanından geçerken duyulan sürekli "uğultu / vızıltı" sesinin (50 Hz şebekede 100 Hz temel tonlu sesin) birincil fiziksel kaynağı nedir?', 'Alternatif manyetik alanda çekirdeğin her yarım periyotta mikroskobik boyutta uzayıp kısalması (manyetostriksiyon) ve sac titreşimleri', ['Bakır sargıların içinden geçen elektronların ses duvarını aşarak şok dalgası üretmesi', 'Sekonder devredeki elektrik sayaçlarının uzaktan trafo merkezine akustik sinyal göndermesi', 'Topraklama çubuğunun yeraltı sularını kaynatarak buhar kabarcıkları çıkarması'], 'Manyetostriksiyon olayı nedeniyle ferromanyetik çekirdek manyetik alanın her tepe değerinde (periyotta iki kez, yani 2f = 100 Hz\'de) boyut değiştirerek mekanik ses titreşimi yayar.'),
  ('Gerçek bir transformatörün sekonder uçları açıkken (hiçbir yük bağlı değilken) primer sargı şebekeye bağlı bırakılırsa elektrik sayacının az da olsa enerji tüketimi yazmasının nedeni nedir?', 'Yüksüz durumda da çekirdekte histerezis ve Fuko (demir) kayıpları ile çok küçük primer bakır kaybının sürmesi', ['Açık bırakılan sekonder uçlarından havaya görünmez elektron demetlerinin sürekli fırlaması', 'Yüksüz transformatörün tam yükteki gücün iki katı kadar ısı enerjisini sargılarda harcaması', 'Elektrik sayaçlarının yalnızca açık devreleri ölçmek üzere hatalı kalibre edilmiş olması'], 'Telefon şarj aleti veya trafo yüksüz prizde bırakıldığında çekirdekte alternatif manyetik akı kurulmaya devam eder ve sürekli "boşta çalışma (demir) kaybı" oluşur.'),
  ('Bir santralin ürettiği 500 kW güç, toplam direnci 8 ohm olan bir hat üzerinden 10 kV etkin gerilimle bir kasabaya gönderiliyor (cosφ = 1). Hattın sonunda kasabaya ulaşan net elektriksel güç kaç kW olur?', '480 kW', ['460 kW', '492 kW', '400 kW'], 'Hat akımı I = P / V = 500.000 / 10.000 = 50 A olur. Hattaki ısı kaybı P_kayıp = I² · R = 50² · 8 = 20.000 W = 20 kW\'tır. Kasabaya ulaşan net güç 500 - 20 = 480 kW bulunur.'),
  ('Bir transformatör çekirdeğinde oluşan Fuko (girdap) akımı kaybı gücü, uygulanan alternatif manyetik alanın frekansı (f) ve sac levha kalınlığı (d) ile nasıl değişir?', 'Hem frekansın karesiyle hem de sac kalınlığının karesiyle doğru orantılı olarak artar', ['Frekansla ters orantılı azalırken sac kalınlığıyla doğru orantılı olarak artar', 'Sac kalınlığından bağımsız olup yalnızca sarım sayısının kareköküyle azalır', 'Frekans arttıkça sıfıra yaklaşır, sac kalınlığı arttıkça sabit bir değerde kalır'], 'İndüklenen girdap emk\'sı f ve kesit genişliği d ile orantılı olduğundan P = ε²/R bağıntısı uyarınca klasik Fuko kaybı f² · d² ile doğru orantılıdır.'),
  ('Verimi %80 olan gerçek bir transformatör 10 dakika boyunca sürekli çalıştırıldığında primerinden 500 W sabit güç çekmektedir. Bu süre içinde transformatörde açığa çıkan toplam kayıp ısı enerjisi kaç kJ olur?', '60 kJ', ['100 kJ', '240 kJ', '12 kJ'], 'Kayıp güç P_kayıp = 500 · (1 - 0,80) = 100 W\'tır. Süre t = 10 · 60 = 600 saniye olduğundan kayıp ısı Q = 100 · 600 = 60.000 J = 60 kJ bulunur.'),
  ('Primerine 220 V alternatif gerilim uygulanan %90 verimli bir transformatörün sekonderinde 44 V gerilim altında çalışan bir motor 18 A akım çekmektedir (güç çarpanları 1 kabul ediliyor). Primer sargıdan çekilen etkin akım kaç A\'dir?', '4 A', ['3,6 A', '3,24 A', '5 A'], 'Sekonder gücü P_s = 44 · 18 = 792 W\'tır. Verim 0,90 olduğundan P_p = 792 / 0,90 = 880 W olur. Primer akımı I_p = 880 / 220 = 4 A bulunur.'),
  ('Bir öğrenci laboratuvarda gerçek bir transformatörün giriş ve çıkışlarına ideal voltmetre ve ampermetreler bağlayarak V_p = 100 V, I_p = 2 A, V_s = 48 V ve I_s = 4 A değerlerini okuyor (yük saf dirençtir). Öğrencinin sarım oranı N_p / N_s = 2 olan bu transformatör için yapacağı hangi çıkarım doğrudur?', 'Hem sargı direnci/kaçak akı kaynaklı küçük bir gerilim düşümü vardır hem de toplam verim %96\'dır', ['Transformatör %100 verimli ideal bir araçtır ancak voltmetre alternatif akımı yanlış ölçmüştür', 'Çıkış akımı giriş akımının iki katı olduğundan transformatör dışarıdan ek enerji üretmektedir', 'Sekonder gerilimi tam 50 V çıkmadığı için çekirdekteki demir levhalar tamamen erimiştir'], 'İdeal olsaydı V_s = 100 / 2 = 50 V olurdu; iç empedans düşümüyle 48 V ölçülmüştür. Giriş gücü 200 W, çıkış gücü 48 · 4 = 192 W olup verim 192 / 200 = %96\'dır.'),
  ('Yüksek gerilim direklerindeki çıplak alüminyum-çelik iletken tellerin demir direklere doğrudan bağlanmayıp cam veya porselen halkalardan oluşan uzun "izolatör zincirleri" ile asılmasının nedeni nedir?', 'Yüksek gerilimli telden topraklanmış metal direğe akım sızmasını ve ark atlamasını engellemek', ['Rüzgarlı havalarda tellerin kopmasını sağlayarak mekanik gerilmeyi sıfırlamak', 'Direklerde biriken yağmur sularını elektroliz ederek hidrojen gazı üretmek', 'Hat üzerindeki alternatif akımın frekansını her direkte sabit 50 Hz\'de kilitlemek'], 'Metal direkler toprağa bağlıdır (0 V); yüz binlerce voltluk iletken ile direk arasında hem yüzey kaçak yolunu uzatmak hem de hava atlamasını önlemek için uzun izolatör dizileri kullanılır.'),
  ('Uzun mesafeli yüksek gerilim hava hatlarında iletken olarak saf bakır yerine "çelik özlü alüminyum iletken" (ACSR) tercih edilmesinin mühendislik gerekçesi nedir?', 'Alüminyumun birim kütle başına iletkenliğinin yüksek ve hafif olması, merkezdeki çeliğin ise mekanik çekme dayanımını sağlaması', ['Alüminyumun özdirencinin bakırdan daha küçük olup aynı kesitte daha az ısı üretmesi', 'Çelik özün manyetik alanı yok ederek Fuko akımlarını tamamen ortadan kaldırması', 'Bakır tellerin açık havada güneş ışığı altında fotoelektrik etkiyle hızla erimesi'], 'Bakır çok ağır ve pahalıdır; alüminyum biraz daha kalın kesitte aynı iletkenliği yarı ağırlıkta sağlar, ortadaki çelik tel ise iki direk arasındaki sarkma ve kopmaya karşı direnç verir.'),
  ('Üç özdeş alçaltıcı transformatörün bulunduğu bir fabrikada her bir transformatör şebekeden 100 kW güç çekmekte ve %95 verimle çalışmaktadır. Bu üç transformatörün soğutma sisteminin ortamdan uzaklaştırması gereken toplam ısı gücü kaç kW\'tır?', '15 kW', ['5 kW', '285 kW', '10 kW'], 'Her bir transformatörün ısı kaybı 100 · (1 - 0,95) = 5 kW\'tır. Üç özdeş transformatörde toplam 3 · 5 = 15 kW ısı açığa çıkar.'),
  ('Gerçek bir transformatörün primer sargısı 500 sarım, sekonder sargısı 100 sarımdır. Primerine 250 V etkin gerilim uygulandığında 1,6 A etkin akım çekilmektedir. Sekondere bağlı saf dirençten 7 A akım geçerken sekonder uçlarındaki gerilim 48 V ölçüldüğüne göre verim yüzde kaçtır?', '%84', ['%80', '%87,5', '%90'], 'Giriş gücü P_p = 250 · 1,6 = 400 W\'tır. Çıkış gücü P_s = 48 · 7 = 336 W olur. Verim η = (336 / 400) · 100 = 336 / 4 = %84 bulunur (sarım sayıları çeldirici fazladan bilgidir).'),
  ('Bir rüzgar türbini 2 MW gücü 4 kV çıkış gerilimiyle üretmektedir. Türbinin dibindeki ideal yükseltici transformatör bu gerilimi 40 kV\'a çıkararak toplam direnci 6 ohm olan iletim hattına veriyor (cosφ = 1). İletim hattında birim zamanda ısıya dönüşen güç kaç kW\'tır?', '15 kW', ['1500 kW', '30 kW', '6 kW'], 'Yükseltici transformatör çıkışında hat gerilimi 40 kV = 4·10⁴ V olduğundan hat akımı I = 2·10⁶ / 4·10⁴ = 50 A olur. Hat kaybı P_kayıp = 50² · 6 = 15.000 W = 15 kW bulunur.'),
  ('Aynı rüzgar türbini 2 MW gücü yükseltici transformatör kullanmadan doğrudan 4 kV gerilimle 6 ohm\'luk aynı hatta verseydi ne gerçekleşirdi?', 'İstenen 500 A akım altında hat kaybı formülde 1,5 MW\'a ulaşarak iletimi ekonomik ve teknik olarak işlevsiz kılardı', ['Hattaki ısı kaybı yine 15 kW olarak kalır, yalnızca alıcı ucundaki frekans düşerdi', 'Düşük gerilim sayesinde iletim telleri soğuyarak üretece fazladan güç geri basardı', 'Hat akımı 5 A değerine düşerek yalıtkan direklerin maliyetini tamamen ortadan kaldırırdı'], '4 kV altında 2 MW için I = 500 A gerekir; I²·R = 250.000 · 6 = 1,5 MW kayıp demektir (hatta gerilim düşümü I·R = 3000 V olup 4 kV kaynağın büyük kısmı yolda tükenir).'),
  ('Evlerde kullanılan modern çok kademeli "anahtarlamalı güç kaynağı" (SMPS) telefon adaptörlerinin, eski tip 50 Hz demir çekirdekli ağır adaptörlere göre çok küçük ve hafif üretilebilmesinin transformatör fiziği açısından temel sırrı nedir?', 'Giriş elektriğinin önce onlarca kilohertz (kHz) yüksek frekansa çevrilmesi sayesinde küçük kesitli ferrit çekirdeğin aynı gücü doyuma girmeden aktarabilmesi', ['Yeni adaptörlerin içinde transformatör yerine yalnızca yüksek dirençli karbon ısıtıcılar kullanılması', 'Bakır sargıların yerine kütlesi sıfır olan vakum tüplerinin manyetik alanı taşıması', 'Yüksek frekansta enerjinin korunumu yasasının esneyerek tek sarımla bin kat güç üretilmesi'], 'V = 4,44 · f · N · B_maks · A_çekirdek bağıntısına göre frekans (f) 50 Hz\'den 50.000 Hz\'e çıkarıldığında çekirdek kesit alanı (A) ve sarım sayısı (N) çok büyük oranda küçültülebilir.'),
  ('Bir fabrikanın ihtiyacı olan 440 kW güç, toplam direnci 0,5 ohm olan kısa bir dağıtım hattı üzerinden fabrika girişinde 2200 V gerilim bulunacak biçimde sağlanmaktadır (cosφ = 1). Bu hat üzerinde birim zamanda ısıya dönüşen kayıp güç kaç kW\'tır?', '20 kW', ['10 kW', '40 kW', '5 kW'], 'Fabrika girişinde çekilen hat akımı I = P / V = 440.000 / 2200 = 200 A olur. Hattaki ısı kaybı P_kayıp = I² · R = 200² · 0,5 = 20.000 W = 20 kW bulunur.'),
  ('Bir transformatör çekirdeğinin yapımında 2 mm kalınlığında 50 adet sac levha kullanmak yerine, aynı toplam kalınlığı verecek biçimde 0,5 mm kalınlığında 200 adet yalıtımlı sac levha kullanılırsa Fuko girdap akımı kaybı yaklaşık nasıl değişir?', 'Levha kalınlığı dörtte birine indiği için Fuko kaybı yaklaşık on altıda birine düşer', ['Toplam demir hacmi değişmediği için Fuko kaybı da hiçbir değişiklik göstermez', 'Levha sayısı dört katına çıktığı için Fuko kaybı da dört katına yükselir', 'Yalıtkan katmanlar manyetik alanı tamamen kestiği için sekonder gerilimi sıfırlanır'], 'Toplam çekirdek hacmi sabitken Fuko kaybı levha kalınlığının karesiyle (d²) orantılıdır; d değeri 1/4\'üne indiğinde kayıp yaklaşık (1/4)² = 1/16 katına iner.'),
  ('Laboratuvarda yapılan "Waltenhofen sarkacı" deneyinde, bakır bir levha güçlü bir elektromıknatısın kutupları arasından sallandırıldığında mıknatıs devresi açıkken serbestçe salınmakta, mıknatısa akım verildiğinde ise kutuplar arasına girerken aniden yavaşlayıp durmaktadır. Levha üzerine tarak gibi ince yarıklar açıldığında frenlemenin büyük ölçüde kalkması neyi kanıtlar?', 'Yarıkların geniş Fuko girdap akımı halkalarını kesintiye uğratarak indüklenen frenleyici manyetik kuvveti ve enerji kaybını azalttığını', ['Bakır levhanın yarıklar açıldığında ferromanyetik özelliğini kaybedip diyamanyetik hale geçtiğini', 'Elektromıknatısın yalnızca dairesel geometrili cisimleri çekip dikdörtgen şeritleri ittiğini', 'Hava direncinin yarıklı yüzeylerde sıfırlanarak mekanik enerjinin arttığını'], 'Tarak biçimli yarıklar, transformatör çekirdeğindeki laminasyonla aynı işlevi görerek geniş girdap akımı yollarını böler ve Fuko akımlarını çok küçük değerlere indirir.'),
  ('Primerine 400 V alternatif gerilim uygulanan gerçek bir transformatörün verimi %90\'dır. Sekonder sargısı 120 V gerilim altında bir ısıtıcıya 15 A akım verdiğine göre transformatörde 1 dakikada açığa çıkan kayıp ısı enerjisi kaç kJ olur?', '12 kJ', ['20 kJ', '10,8 kJ', '15 kJ'], 'Çıkış gücü P_s = 120 · 15 = 1800 W\'tır. Verim %90 olduğundan giriş gücü P_p = 1800 / 0,90 = 2000 W ve kayıp güç P_kayıp = 2000 - 1800 = 200 W olur. 60 saniyede Q = 200 · 60 = 12.000 J = 12 kJ ısı açığa çıkar.'),
  ('Bir güneş enerjisi santralinde eviricilerden (inverter) çıkan 600 kW alternatif güç, verimi %96 olan bir yükseltici transformatörden geçirilerek iletim hattına verilmektedir. İletim hattında da 14 kW ısı kaybı oluştuğuna göre şehir şebekesine ulaşan net güç kaç kW olur?', '562 kW', ['576 kW', '546 kW', '570 kW'], 'Yükseltici transformatör çıkış gücü P_1 = 600 · 0,96 = 576 kW olur. İletim hattındaki 14 kW kayıp çıkarıldığında şehre ulaşan güç 576 - 14 = 562 kW bulunur.'),
  ('Kablosuz şarj sistemlerinde cihaz ile şarj pedi arasındaki mesafe birkaç santimetre açıldığında şarj veriminin hızla düşmesinin transformatör ilkeleri açısından temel nedeni nedir?', 'Aradaki hava boşluğu büyüdükçe manyetik akı kaçağının artması ve sekonder sargıyı kesen akının azalması', ['Mesafe açıldığında alternatif akımın frekansının sıfırlanarak doğru akıma dönüşmesi', 'Hava katmanının ferromanyetik doyuma ulaşarak primer sargıyı kısa devre etmesi', 'Sekonder bobindeki sarım sayısının mesafeyle ters orantılı olarak azalması'], 'Demir çekirdek yerine hava aralığı büyüdüğünde primerin oluşturduğu manyetik alan çizgilerinin büyük bölümü sekonder halkadan geçmeden kendi üzerine kapanır (kuplaj katsayısı düşer).'),
];
